insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('mayaguana-bahamas', '11C', 'Mayaguana', 'Bahamas', 'The easternmost island of The Bahamas', 'future', 'verified', 'mountainValley', 'Bahamas', '{"wildlife","diveglobal","tropical","adventure"}', '{"secluded","remote","coastal","wild"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/bahamas","verified":"2026-10-03"},"jewels":[{"name":"Booby Cay","source":"https://www.bahamas.com/natural-wonders/booby-cay","accessed":"2026-10-03","si":["wildlife","expedition","tropical"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"Located east of mainland Mayaguana, Booby Cay gets its name from the flock of brown boobies that call it home. It''s also the natural habitat for small endemic rock iguanas, and descendants of wild goats left behind by early settlers.\" The Ministry page gives the Administrator''s Office, (242) 339-3100, and states no boat access or operator.","commission_status":"none","booking_route":"none needed for the place itself - the Ministry page names no boat or operator; Administrator''s Office (242) 339-3100"},{"name":"Mayaguana''s offshore reefs, walls and drop-offs","source":"https://www.bahamas.com/islands/mayaguana","accessed":"2026-10-03","si":["diveglobal","ocean","adventure"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"The underwater world that surrounds Mayaguana is as healthy and untouched as you might expect. Dive offshore reefs in the 45-60 ft range, breathtaking walls and drop-offs, even a cave system.\" No dive shop is named on the Ministry page.","commission_status":"none","booking_route":"none needed for the reefs themselves - no dive operator is named on the Ministry page"},{"name":"Horse Pond Beach","source":"https://www.bahamas.com/islands/mayaguana","accessed":"2026-10-03","si":["tropical","family"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Located 10 miles east of Abraham''s Bay, Horse Pond Beach is known to locals as an excellent spot for crabbing - hunting for land crabs hiding in crevices of limestone rocks.\"","commission_status":"none","booking_route":"none needed - a beach"},{"name":"Mayaguana Baycaner Beach Resort","source":"https://www.bahamas.com/hotels/baycaner-beach-resort","accessed":"2026-10-03","si":["tropical","diveglobal","adventure"],"commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":4,"blurb":"The Ministry of Tourism listing, in the hotel''s words: \"Our 16-room hotel is located in a corner of a quiet beach, and your room is just steps away from it. The atmosphere is very laidback, but we do quite a bit of fly fishing, scuba diving, and snorkeling here.\" Baycaner Avenue (Pirate''s Well per the Caribbean Birding Trail, run by Earnel ''Shorty'' Brown); listed amenities include Bar & Lounge, Fishing Guide, Handicap Accessible, On the Beach, Restaurant, WiFi. The two websites tied to it did not serve the hotel on 2026-10-03: baycanerbeach.com now carries an unrelated gambling page and baycanerbeachresort.com returned an expired certificate.","commission_status":"unknown","booking_route":"phone/email only - (242) 339-3726, baycanerbeach@gmail.com (Ministry listing); no working booking engine found"},{"name":"Flats fly fishing for bonefish, permit and tarpon","source":"https://www.islands.com/1572832/underrated-island-mayaguana-bahamas-pristine-beauty-secluded-beaches/","accessed":"2026-10-03","si":["adventure","ocean","tropical"],"commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":5,"blurb":"The Ministry frames the island as \"A Pirate Stronghold Turned Prized Fishing Spot\" (bahamas.com); Islands.com (May 4, 2024) lists \"Fly fishing for bonefish, permit, and tarpon\" along with lure fishing and spearfishing; the Baycaner''s Ministry listing names a \"Fishing Guide\" among its amenities. No independent fishing guide or lodge on Mayaguana was found on a page read.","commission_status":"unknown","booking_route":"through the Baycaner''s fishing guide, phone/email only - (242) 339-3726 (Ministry listing)"},{"name":"Blackwood Point flamingo colony","source":"https://caribbeanbirdingtrail.org/sites/bahamas/mayaguana/","accessed":"2026-10-03","si":["wildlife","expedition"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"The Caribbean Birding Trail names \"Blackwood Point\" east of Pirate''s Well for its flamingo colony, and lists the American Flamingo among the island''s Bahamian specialties, with the endemic Bahama Woodstar. It says plainly: \"no guides available\".","commission_status":"none","booking_route":"none needed - a natural site; no guide is offered (Caribbean Birding Trail)"},{"name":"Betsy Bay, Abraham''s Bay and Pirate''s Well homecoming festivals","source":"https://www.bahamas.com/islands/mayaguana","accessed":"2026-10-03","si":["culture","culinary"],"tier_absent_reason":"not-sold","wells":["activities","eat"],"draw_rank":7,"blurb":"\"Try land crabs served with grits, rice, or dumplings, fish salad, boiled conch, and more at the Betsy Bay, Abraham''s Bay, and the Pirate''s Well homecoming festivals.\" No dated edition of any of the three was found on a page read.","commission_status":"none","booking_route":"none needed - community festivals; no ticketing seen"},{"name":"Curtis Creek","source":"https://caribbeanbirdingtrail.org/sites/bahamas/mayaguana/","accessed":"2026-10-03","si":["wildlife","adventure","ocean"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"On the north shore, with \"tidal flats\" named as a birding site by the Caribbean Birding Trail; Wikivoyage lists \"Curtis Creek mangrove paddling and snorkeling\", and Islands.com says canoes rent \"for around $25 at the resort\" (the Baycaner).","commission_status":"none","booking_route":"none needed for the creek - canoe hire through the Baycaner per Islands.com, phone/email (242) 339-3726"},{"name":"Beach picnics and shore snorkelling","source":"https://www.bahamas.com/islands/mayaguana","accessed":"2026-10-03","si":["tropical","family","ocean"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"The stretches of picturesque beaches on Mayaguana are perfect for picnicking, sunbathing, shelling, and strolling. With unbelievable aquamarine water, you can snorkel just offshore to see coral heads, sand dollars, and starfish.\"","commission_status":"none","booking_route":"none needed - public beaches"},{"name":"Paradise Villas, Abraham''s Bay","source":"https://en.wikivoyage.org/wiki/Mayaguana","accessed":"2026-10-03","si":["tropical","adventure"],"commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":10,"blurb":"Wikivoyage: \"Simple air-conditioned rooms with restaurant\" in Abraham''s Bay, +1 242 339-3065, and \"Dootch offers reef and fishing excursions\". No own website or Ministry listing was found, so this rests on a guide site.","commission_status":"unknown","booking_route":"phone only - +1 242 339-3065 (Wikivoyage)"},{"name":"Island tours with Glen and \"Zoom\" (Floyd Farrington)","source":"https://en.wikivoyage.org/wiki/Mayaguana","accessed":"2026-10-03","si":["culture","adventure"],"commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities","move"],"draw_rank":11,"blurb":"Wikivoyage lists \"Island tours with Glen and ''Zoom'' (Floyd Farrington): 1(242)439-4171\", and notes locals provide transport for USD $20-40 a day. No own page found.","commission_status":"unknown","booking_route":"phone only - 1 (242) 439-4171 (Wikivoyage)"},{"name":"Velva and Elvin''s place, Pirate''s Well","source":"https://en.wikivoyage.org/wiki/Mayaguana","accessed":"2026-10-03","si":["culinary","culture"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":12,"blurb":"Wikivoyage''s one drinking listing: \"Velva and Elvin''s place in Pirates Well: 1(242)339-3068\". It describes island food as fresh fish, conch and lobster with rice, beans and locally grown watermelon and sweet potatoes. No own page found.","commission_status":"unknown","booking_route":"phone only - 1 (242) 339-3068 (Wikivoyage)"},{"name":"Saturday airport parties","source":"https://en.wikivoyage.org/wiki/Mayaguana","accessed":"2026-10-03","si":["culture","entertainment"],"tier_absent_reason":"not-sold","wells":["eat"],"draw_rank":13,"blurb":"Wikivoyage lists \"Weekly Saturday airport parties featuring local food and reggae\". Not confirmed on any other page read, and written before the new terminal opened on February 27, 2026.","commission_status":"none","booking_route":"none needed - a community gathering"}],"faq":[{"q":"How do I get to Mayaguana?","a":"By air on Bahamasair from Nassau. Its booking engine lists the Nassau (NAS) - Mayaguana (MYG) route; for the week of October 4-10, 2026 it showed one flight, UP-425 on Monday October 5, departing Nassau 9:30 AM and arriving 12:15 PM with \"1 Stop\". Check the carrier for your own dates.","source":"https://book.bahamasair.com/ibe/availability?tripType=ONE_WAY&language=en&dateFormat=dd/MM/yyyy&depPort=NAS&arrPort=MYG&adult=1&child=0&infant=0&currency=USD&departureDate=05%20Oct%202026","accessed":"2026-10-03"},{"q":"What is Mayaguana''s airport code?","a":"MYG. The Ministry of Tourism: Mayaguana Airport (MYG), \"Located near Abraham''s Bay, it is the only airport serving the island with regularly scheduled service to Nassau.\"","source":"https://www.bahamas.com/islands/mayaguana","accessed":"2026-10-03"},{"q":"Does Mayaguana have a new airport?","a":"A new terminal. The Tribune reported (March 2, 2026) that the Prime Minister opened a $2.1 million terminal on February 27, 2026: \"just under 3,200 square feet\", fully air-conditioned, with ticketing, 30-passenger seating, baggage screening and a police station, on a 6,700-foot runway.","source":"http://www.tribune242.com/news/2026/mar/02/pm-opens-21m-mayaguana-airport-tied-to-2000-job-seaport-project","accessed":"2026-10-03"},{"q":"What is the Mayaguana port project?","a":"A planned cruise and cargo port, in three phases: a temporary marine offloading facility and deep-water port, then a cruise ship terminal, then a deep-water transshipment port. It is owned by the Government of The Bahamas, the Mayaguana Island Development Fund and Global Lead Consultant Group Limited, operated by Mayaguana Port Group Ltd., and as of April 22, 2026 was \"expected to move into detailed planning in the coming months\". It is not built.","source":"https://www.caribjournal.com/2026/04/22/bahamas-new-cruise-port-mayaguana/","accessed":"2026-10-03"},{"q":"Where should I stay in Mayaguana, Bahamas?","a":"The one hotel listed by the Ministry of Tourism is the Mayaguana Baycaner Beach Resort on Baycaner Avenue: \"Our 16-room hotel is located in a corner of a quiet beach, and your room is just steps away from it.\" It books by phone, (242) 339-3726, or baycanerbeach@gmail.com.","source":"https://www.bahamas.com/hotels/baycaner-beach-resort","accessed":"2026-10-03"},{"q":"What is Mayaguana known for?","a":"Solitude, fishing and reefs. The Ministry of Tourism calls it \"More isolated and less developed than any other island in The Bahamas\" and \"A Pirate Stronghold Turned Prized Fishing Spot\", and says \"Mayaguana is the only island in The Bahamas that conserves its original Arawak name.\"","source":"https://www.bahamas.com/islands/mayaguana","accessed":"2026-10-03"},{"q":"How far is Mayaguana from Nassau?","a":"About 560 km (350 mi): Mayaguana is \"About 100 km (62 mi) north of Great Inagua and 560 km (350 mi) southeast of the capital Nassau\".","source":"https://en.wikipedia.org/wiki/Mayaguana","accessed":"2026-10-03"},{"q":"How far is Mayaguana from Turks and Caicos?","a":"About 100 km (62 mi). Settlement began in 1812, \"when people began to migrate from the Turks and Caicos Islands, which are located about 100 km (62 mi) southeast.\"","source":"https://en.wikipedia.org/wiki/Mayaguana","accessed":"2026-10-03"},{"q":"What is the population of Mayaguana?","a":"208 in the 2022 census, as given in the Wikipedia infobox (citing the Government''s preliminary 2022 census results); the 2010 census counted 277.","source":"https://en.wikipedia.org/wiki/Mayaguana","accessed":"2026-10-03"},{"q":"How big is Mayaguana?","a":"\"It has an area of about 280 km2 (110 sq mi)\", and it is \"the easternmost island and district of The Bahamas\".","source":"https://en.wikipedia.org/wiki/Mayaguana","accessed":"2026-10-03"}],"seo":{"meta_title":"Mayaguana, Bahamas: Booby Cay, Reefs, Beaches & Where to Stay | TravelWell","meta_description":"Mayaguana, the least developed Bahamas island: Booby Cay, offshore reefs and walls, Horse Pond Beach, homecoming festivals and the 16-room Baycaner.","slug":"mayaguana-bahamas","primary_keyword":"Mayaguana Bahamas","jsonld_type":"TouristDestination"},"hero":{"query":"Mayaguana Bahamas"}}'::jsonb, 7),
  ('ragged-island-bahamas', '11C', 'Ragged Island', 'Bahamas', 'More bonefish than people', 'future', 'verified', 'mountainValley', 'Bahamas', '{"sports","expedition","sailing","culture","tropical"}', '{"remote","secluded","rugged","serene","coastal"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/bahamas","verified":"2026-10-03"},"jewels":[{"name":"Lost Key Lodge","source":"https://lostkeylodge.com/pricing-and-availability","accessed":"2026-10-03","si":["sports","expedition","adventure","ocean"],"commission":"operator","tier_absent_reason":"not-established","wells":["stay","activities","eat"],"draw_rank":1,"blurb":"The island''s fly-fishing lodge, \"Accommodating 4 anglers maximum\", fishing \"easily-waded white sand flats as well as hidden, unspoiled mangrove creeks\" for bonefish, permit and barracuda, plus tarpon and blue-water marlin, tuna, wahoo and sailfish. \"The cost for 7 nights 6 days of fishing is $4,995.00. This includes everything once you reach the airport at Lost Key Lodge\"; blue-water charters \"$400.00 per day per person\"; the Georgetown charter \"$850 per person round trip\" is extra. Fall 2026 and Spring 2027 weeks read Full; Fall 2027 weeks show open spaces. Fly Fisherman (23 May 2024) says it is co-owned by lifelong resident Phicol Wallace and opened in March 2021 (https://www.flyfisherman.com/editorial/ragged-island-fishing-jumentos-cays/498375, accessed 2026-10-03).","commission_status":"unknown","booking_route":"phone/email only (530-941-8524, info@lostkeylodge.com)"},{"name":"Ragged Island bonefish flats","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03","si":["sports","ocean","adventure"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"The island is a haven for avid fishermen, with its unparalleled flats ideal for bonefishing.\" Beyond the flats: \"It''s not uncommon to snag an abundance of grouper, snapper, barracuda, tuna, and kingfish during a one-day expedition on the water.\"","commission_status":"none","booking_route":"none needed - public flats; guided fishing through Lost Key Lodge or Alvin Munroe"},{"name":"Alvin Munroe","source":"https://www.bahamas.com/vendor/alvin-munroe","accessed":"2026-10-03","si":["sports","wildlife","ocean"],"commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":3,"blurb":"Fishing guide: \"As a lifelong fisherman and native of Ragged Island, I know all of the best places for whatever kind of catch you want.\" \"There is great bonefishing on the west side of the mainland and the cays\", trolling for mackerel and kingfish, bottom fishing for snappers and Margaret fish, and \"excursions to the cays for birding, picnicking or snorkeling\". \"Reservations are required at least one week in advance.\" The listing is undated; current operation was not confirmed on any other page.","commission_status":"unknown","booking_route":"phone/email only ((242) 432-1825, Silver Tail Club, Charles Street, Duncan Town)"},{"name":"Jumentos Cays","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03","si":["sailing","expedition","yacht","tropical"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"The surrounding Jumentos Cays offer a ready-made island hopping itinerary for curious travellers. If you''ve dreamt of having a private beach, or even a private island, all you need is a boat.\" The chain of \"islets, cays, and rocks\" stretches \"over 100 miles\" and the cays are uninhabited.","commission_status":"none","booking_route":"none needed - open water; reached by own or chartered boat"},{"name":"Hog Cay","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03","si":["tropical","sailing","wildlife","romance"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"Just north of mainland Ragged Island lies Hog Cay. Its sandy shores are popular with Ragged Islanders, perfect for all-day picnics and celebrations\"; \"a great ecotourism destination that offers plenty of birdwatching opportunities, bonfires, and romantic picnic spots.\" \"Spend the day on the cay, and end it with a bonfire on the beach.\"","commission_status":"none","booking_route":"none needed - public cay reached by boat"},{"name":"Valentine''s Day Cook Out on Hog Cay","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03","si":["culture","sailing","romance"],"tier_absent_reason":"not-sold","wells":["activities","eat"],"draw_rank":6,"blurb":"bahamas.com calls it \"a famous annual Valentine''s Day celebration\" on Hog Cay. The Bahamian Project names Maxine Wallace of Maxine Drug and Groceries as \"the founder and driving force behind the popular Valentine''s Day Cook Out on Hog Cay\": \"The annual Cook Out is Maxine''s way of saying thank you to the visitors, many of whom come back every year\" (https://www.bahamianproject.com/2024/08/exuma-ragged-island-mailboat/, accessed 2026-10-03). No dated edition was published by an organiser.","commission_status":"unknown","booking_route":"none observed - no organiser page or booking found"},{"name":"Duncan Town","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03","si":["culture","sailing","senior"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"One lighthouse, one harbour, and a salt pond that stretches the length of Duncan Town, Ragged Island''s one and only settlement. Residents still harvest salt from their family plots.\" Ragged Islanders \"build boats, booms, and masts for sailing sloops, race boats in regattas, and fish\", and \"nearly every home is built to have a breathtaking view of the ocean.\"","commission_status":"none","booking_route":"none needed - public settlement"},{"name":"Ragged Island Salt Ponds","source":"https://www.bahamas.com/vendor/ragged-island-salt-ponds","accessed":"2026-10-03","si":["culture","expedition"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"These salt ponds are remnants of the thriving salt industry that formerly existed on Ragged Island\", developed in the 19th century by Duncan Taylor and his brother Major Taylor from Long Island. Production continues at reduced levels: the government manages the largest reservoir and the rest are family plots; \"Rainwater settles in the ponds and salt forms as it evaporates\", raked by hand in the April-to-August harvest and sold locally or shipped to Nassau.","commission_status":"none","booking_route":"none needed - visible from the settlement; listing phone (242) 344-1508"},{"name":"Duncan Town''s shared church","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03","si":["culture","pilgrimage"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Three Religions. One Roof.\" \"Because the population is so small, members of three different religious denominations gather at the same church on Sundays, to celebrate together.\" The page does not name the church.","commission_status":"none","booking_route":"none needed - a place of worship"},{"name":"Pigeon Cay and the Bishop Churton memorial cross","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03","si":["culture","pilgrimage","sailing"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Pigeon Cay is visible off the coast of Ragged Island near Gun Point. Look for the memorial cross honoring Henry Norris Churton, Bishop of Nassau, who died at sea when his boat capsized in 1904.\"","commission_status":"none","booking_route":"none needed - seen from the coast near Gun Point"},{"name":"Hill Top View Bar","source":"https://bahamas.com/vendor/hill-top-view-bar","accessed":"2026-10-03","si":["culture","culinary"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":11,"blurb":"\"This is a great place to meet the locals, who hang out here after a long day of fishing. It has a very quiet atmosphere, with no music or games, which allows for uninterrupted conversation.\" Soft drinks, beer and mixed cocktails; manager Mr. Raphael Wallace. The listing is undated and gives no hours; whether it reopened after Irma was not confirmed on any page read.","commission_status":"unknown","booking_route":"phone/email only ((242) 344-1505, Taylor Street, Duncan Town)"},{"name":"People-to-People local dishes","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03","si":["culinary","culture"],"tier_absent_reason":"not-sold","wells":["eat"],"draw_rank":12,"blurb":"\"Join People-to-People volunteers for a taste of favourite local dishes like grilled and steamed fish, cracked conch, free-range mutton, and turtle soup.\" The page names no host, day or place.","commission_status":"unknown","booking_route":"none observed - no booking contact on the page"},{"name":"Maxine Drug and Groceries","source":"https://www.bahamianproject.com/2024/08/exuma-ragged-island-mailboat/","accessed":"2026-10-03","si":["culture","sailing"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop","eat"],"draw_rank":13,"blurb":"Duncan Town''s store, run by Maxine Wallace, founder of the Hog Cay Valentine''s Day Cook Out: \"Maxine who runs ''Maxine Drug and Groceries'' and is the founder and driving force behind the popular Valentine''s Day Cook Out on Hog Cay\" (March 2024 voyage, posted 18 August 2024). No own page was found; this is a guide-site source.","commission_status":"unknown","booking_route":"none needed - a shop; no contact published"},{"name":"Marjorie Wallace straw and shell craft","source":"https://bahamas.com/vendor/marjorie-wallace","accessed":"2026-10-03","si":["culture"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop"],"draw_rank":14,"blurb":"\"Mrs. Wallace is known for her straw and shell craft, and she uses the local Androsia batik in her designs\": straw bags, mats, curtains, place mats and cushions, and jewellery from seashells, fish scales, conch and whelk shells and seeds. The listing is undated; current trading was not confirmed on any other page.","commission_status":"unknown","booking_route":"phone/email only ((242) 344-1505, Taylor Street, Duncan Town)"},{"name":"Captain C mailboat","source":"https://www.bahamianproject.com/2024/09/captain-c-and-the-maycock-brothers/","accessed":"2026-10-03","si":["expedition","culture"],"commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":15,"blurb":"The freight lifeline: \"Nassau, Staniel Cay, Black Point, Farmer''s Cay, Barraterre, Duncan Town and back\", on the route since 2001 under the Maycock family; in September 2024 \"A renovation of the Captain C will be made this year in Louisianna, where it was first built.\" The page does not say it carries passengers, and no current schedule or fare was read.","commission_status":"unknown","booking_route":"none observed - no schedule or booking contact on the page"}],"faq":[{"q":"What is Ragged Island known for?","a":"Bonefishing. \"There''s more bonefish than people on Ragged Island Bahamas, hence why it''s known as a fisherman''s paradise.\" The official site also names its salt ponds - residents \"still harvest salt from their family plots\" - its boat builders, and the one church where \"members of three different religious denominations gather\" on Sundays.","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03"},{"q":"Where is Ragged Island, Bahamas?","a":"At the southern end of the Jumentos chain: \"Great and Little Ragged Island lie at the end of a chain of islets, cays, and rocks that stretch over 100 miles.\" Its one settlement is Duncan Town. Lost Key Lodge places the island 60 miles north of Cuba (https://lostkeylodge.com/, accessed 2026-10-03).","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03"},{"q":"How do I get to Ragged Island, Bahamas?","a":"By charter flight or boat. The official site: \"The Duncan Town Airport is the only airport servicing Ragged Island\" and \"most travellers stay in nearby Long Island and venture over for a day, via boat or charter flight.\" Lost Key Lodge routes its anglers through Georgetown, Exuma (\"American Airlines is very convenient out of Atlanta\") and arranges a charter to Duncan Town at \"$850 per person round trip\" (https://lostkeylodge.com/pricing-and-availability, accessed 2026-10-03).","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03"},{"q":"Does Ragged Island, Bahamas have an airport?","a":"Yes: \"The Duncan Town Airport is the only airport servicing Ragged Island.\" No scheduled airline route to it was found - Bahamasair''s homepage does not list it (https://www.bahamasair.com/, accessed 2026-10-03) - and visitors arrive by charter flight.","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03"},{"q":"Are there hotels on Ragged Island, Bahamas?","a":"One fishing lodge was found. Lost Key Lodge takes \"4 anglers maximum\" on a \"7 nights 6 days of fishing\" package at $4,995.00 (https://lostkeylodge.com/pricing-and-availability, accessed 2026-10-03). For other visitors, the official site says \"most travellers stay in nearby Long Island and venture over for a day, via boat or charter flight.\"","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03"},{"q":"What is the fishing like on Ragged Island, Bahamas?","a":"Flats and offshore. \"The island is a haven for avid fishermen, with its unparalleled flats ideal for bonefishing\", and \"It''s not uncommon to snag an abundance of grouper, snapper, barracuda, tuna, and kingfish during a one-day expedition on the water.\" Local guide Alvin Munroe says \"There is great bonefishing on the west side of the mainland and the cays\" (https://www.bahamas.com/vendor/alvin-munroe, accessed 2026-10-03).","source":"https://www.bahamas.com/islands/ragged-island","accessed":"2026-10-03"},{"q":"What is the population of Ragged Island, Bahamas?","a":"The 2022 census recorded 44 residents, down from 72 in 2010. A March 2024 visit reported \"The 65 residents are served by electricity from BEC, a reverse osmosis plant for water, roads and an airstrip\" (https://www.bahamianproject.com/2024/08/exuma-ragged-island-mailboat/, accessed 2026-10-03).","source":"https://en.wikipedia.org/wiki/Ragged_Island,_Bahamas","accessed":"2026-10-03"},{"q":"What is the history of Ragged Island, Bahamas?","a":"Salt, then storm. The salt ponds were \"developed in the 19th century by Duncan Taylor and his brother Major Taylor\", and Duncan Town is named for him (https://www.bahamas.com/vendor/ragged-island-salt-ponds, accessed 2026-10-03). The industry peaked in the 1930s before declining. On 8 September 2017 Hurricane Irma struck Duncan Town directly and the prime minister ordered an evacuation; a solar farm completed by February 2020 was built to supply \"at least 90% of the island''s energy needs.\"","source":"https://en.wikipedia.org/wiki/Ragged_Island,_Bahamas","accessed":"2026-10-03"},{"q":"What is the weather like on Ragged Island, Bahamas?","a":"The island sits in the Atlantic hurricane belt: \"The Atlantic hurricane season runs from June 1 to November 30.\" \"The peak of the Atlantic hurricane season is September 10, with most activity occurring between mid-August and mid-October.\" Hurricane Irma struck Duncan Town on 8 September 2017.","source":"https://www.nhc.noaa.gov/climo/","accessed":"2026-10-03"}],"seo":{"meta_title":"Ragged Island, Bahamas: Bonefishing, Duncan Town & the Jumentos Cays | TravelWell","meta_description":"Ragged Island: bonefish flats, Lost Key Lodge, Duncan Town''s salt ponds, Hog Cay and the Jumentos Cays, reached by charter flight to Duncan Town Airport.","slug":"ragged-island-bahamas","primary_keyword":"Ragged Island Bahamas","jsonld_type":"TouristDestination"},"hero":{"query":"Ragged Island Bahamas"}}'::jsonb, 8),
  ('rum-cay-bahamas', '11C', 'Rum Cay', 'Bahamas', 'Petroglyphs and the HMS Conqueror wreck', 'future', 'verified', 'mountainValley', 'Bahamas', '{"diveglobal","culture","wildlife","yacht","adventure"}', '{"secluded","remote","serene","historic","tropical"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/bahamas","verified":"2026-10-03"},"jewels":[{"name":"HMS Conqueror wreck, Sumner Point Reef","source":"https://www.bahamas.com/islands/rum-cay","accessed":"2026-10-03","si":["diveglobal","culture","adventure"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"In 1861, the 101-gun HMS Conqueror, Britain''s first propellor-driven warship, wrecked on Sumner Point Reef\"; the Ministry''s diving page lists \"HMS Conqueror, Rum Cay\" among its stand-out shipwreck dives","commission_status":"none","booking_route":"none needed - a public wreck site; bahamas.com names no dive operator on Rum Cay"},{"name":"The Grand Canyon wall dive","source":"https://www.bahamas.com/islands/rum-cay","accessed":"2026-10-03","si":["diveglobal","adventure"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"From the 60ft walls of the ''Grand Canyon'', to steep drop-offs and tunnel systems, divers can take their pick\" in Rum Cay''s \"gin-clear turquoise waters\"","commission_status":"none","booking_route":"none needed - a public reef site; bahamas.com names no dive operator on Rum Cay"},{"name":"Hartford Cave","source":"https://www.bahamas.com/islands/rum-cay","accessed":"2026-10-03","si":["culture","adventure","hiking"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Hartford Cave holds the secrets of the Lucayan-Arawak people that once lived here\" - Lucayan petroglyphs the Ministry calls \"perhaps the largest display of such art in The Bahamas\"","commission_status":"none","booking_route":"none needed - bahamas.com lists no fee or booking"},{"name":"Conception Island National Park","source":"https://www.bahamas.com/natural-wonders/conception-island","accessed":"2026-10-03","si":["wildlife","diveglobal","yacht","sailing"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"Measuring 7-9 km2\", \"a large protected cove with shallow water and groves of stag-horn coral you can swim through\", \"essential habitat for nesting seabirds and green turtles\", \"great for snorkeling and diving\"; the Ministry''s Rum Cay page links it as an offshore highlight. Contact listed: Bahamas National Trust, (242) 393-1317, bnt@bnt.bs","commission_status":"none","booking_route":"none observed - the page lists the Bahamas National Trust contact, (242) 393-1317, and no booking or fee"},{"name":"Port Nelson and the Sir Milo Butler square","source":"https://www.bahamas.com/islands/rum-cay","accessed":"2026-10-03","si":["culture","senior"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"Today, Port Nelson is the only inhabited town in sleepy Rum Cay\", with street signs shaped like the island and \"the town square named for The Bahamas'' first Governor-General, Sir Milo Butler, a Rum Cay native\"","commission_status":"none","booking_route":"none needed - a public town"},{"name":"Northern-coast surf beaches","source":"https://www.bahamas.com/islands/rum-cay","accessed":"2026-10-03","si":["tropical","adventure"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"Rum Cay''s northern coast in particular offers perfect surf conditions on undisturbed beaches\"; the Ministry also names \"secret surf spots\" and \"miles of white sand beaches\"","commission_status":"none","booking_route":"none needed - free public beaches"},{"name":"Kay''s Restaurant & Sand Bar","source":"https://www.bahamas.com/plan-your-trip/restaurants/kays-restaurant-sand-bar","accessed":"2026-10-03","si":["culinary","yacht","culture"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":7,"blurb":"King Street, Port Nelson: \"We serve home-cooked Bahamian dishes for breakfast, lunch and dinner, in an island-style setting\" - conch, fish, lobster, beef and mutton; listed hours \"Daily 7:00 a.m. - 10:00 p.m.\"; a \"Crab-eating Contest during crab season\". A cruiser reported on noonsite in June 2017 that Kaye''s \"is now also the island store in one corner\"","commission_status":"unknown","booking_route":"phone/email only ((242) 331-2816, lastchancerc@yahoo.com)"},{"name":"Port Nelson anchorage","source":"https://www.noonsite.com/place/bahamas/out-islands/rum-cay/","accessed":"2026-10-03","si":["yacht","sailing"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"Cruisers on noonsite: in March 2016 \"The government dock is mostly destroyed from Hurricane Joaquin, and the mail boat now uses part of the old marina instead\"; in June 2017 \"the marina entrance completely closed in with sand\" and \"the marina is closed and the ownership is still tied up in court\". Boats anchor off Port Nelson; no current marina is confirmed","commission_status":"none","booking_route":"none needed - an open anchorage; no marina booking exists"},{"name":"Southern Air Charter, Nassau to Rum Cay","source":"https://www.bahamas.com/islands/rum-cay/getting-to-rum-cay","accessed":"2026-10-03","si":["adventure","privatejet"],"commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly","move"],"draw_rank":9,"blurb":"The Ministry: \"Southern Air Charter operates flights to Rum Cay once per week ~ 45 minutes\" from Nassau (NAS) into Port Nelson Airport (RCY), \"The sole airport serving Rum Cay\"; the carrier offers \"private charters throughout the Bahamas, Florida and the Caribbean\"","commission_status":"unknown","booking_route":"carrier website and phone ((242) 377-2017, (954) 302-3107, southernairbah@gmail.com) - https://www.southernaircharter.com/"},{"name":"The Lady Francis mail boat","source":"https://www.bahamas.com/islands/rum-cay/getting-to-rum-cay","accessed":"2026-10-03","si":["adventure","ocean"],"commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":10,"blurb":"\"The Lady Francis departs weekly from Potter''s Cay Dock, Nassau to Rum Cay, time is approximately 48 to 72 hours (or 2 to 3 days)\"","commission_status":"unknown","booking_route":"not stated on the page - departs Potter''s Cay Dock, Nassau"}],"faq":[{"q":"How do I get to Rum Cay, Bahamas?","a":"By air or by mail boat from Nassau. The Ministry of Tourism: \"Southern Air Charter operates flights to Rum Cay once per week ~ 45 minutes\" from Nassau (NAS), and \"The Lady Francis departs weekly from Potter''s Cay Dock, Nassau to Rum Cay, time is approximately 48 to 72 hours (or 2 to 3 days).\"","source":"https://www.bahamas.com/islands/rum-cay/getting-to-rum-cay","accessed":"2026-10-03"},{"q":"What airport serves Rum Cay?","a":"\"Port Nelson Airport (RCY): The sole airport serving Rum Cay.\" The Ministry says it receives Southern Air Charter''s weekly flight from Nassau, about 45 minutes.","source":"https://www.bahamas.com/islands/rum-cay/getting-to-rum-cay","accessed":"2026-10-03"},{"q":"What is the Rum Cay airport code?","a":"RCY. The Ministry of Tourism lists \"Port Nelson Airport (RCY)\" as \"The sole airport serving Rum Cay.\"","source":"https://www.bahamas.com/islands/rum-cay/getting-to-rum-cay","accessed":"2026-10-03"},{"q":"Where is Rum Cay, Bahamas?","a":"In the south-central Bahamas, \"20 miles (32 km) southwest of San Salvador Island\". Its main settlement is Port Nelson.","source":"https://en.wikipedia.org/wiki/Rum_Cay","accessed":"2026-10-03"},{"q":"What is Rum Cay known for?","a":"The Ministry of Tourism calls it \"one of the best-kept secrets in The Bahamas\", home to \"historical ruins, vivid coral reefs, miles of white sand beaches, and thrilling surf\": the 1861 wreck of HMS Conqueror on Sumner Point Reef, Hartford Cave''s Lucayan-Arawak petroglyphs, the 60ft walls of the ''Grand Canyon'' dive, and surf on the northern coast.","source":"https://www.bahamas.com/islands/rum-cay","accessed":"2026-10-03"},{"q":"What is the population of Rum Cay?","a":"\"a population was recorded as 90 as of 2022.\" Port Nelson is the only inhabited town.","source":"https://en.wikipedia.org/wiki/Rum_Cay","accessed":"2026-10-03"},{"q":"How big is Rum Cay?","a":"\"It measures 30 square miles (78 km2) in area.\"","source":"https://en.wikipedia.org/wiki/Rum_Cay","accessed":"2026-10-03"},{"q":"Are there hotels on Rum Cay, Bahamas?","a":"The Ministry of Tourism points visitors to a neighbouring island: \"Make nearby Long Island your home base, and hop over to Rum Cay for the day via boat or charter flight.\" No on-island hotel was confirmed by a current source in this build.","source":"https://www.bahamas.com/islands/rum-cay","accessed":"2026-10-03"},{"q":"Where can I eat on Rum Cay, Bahamas?","a":"The Ministry of Tourism lists Kay''s Restaurant & Sand Bar on King Street, Port Nelson: \"We serve home-cooked Bahamian dishes for breakfast, lunch and dinner, in an island-style setting\", with conch, fish, lobster, beef and mutton; listed hours \"Daily 7:00 a.m. - 10:00 p.m.\"; phone (242) 331-2816.","source":"https://www.bahamas.com/plan-your-trip/restaurants/kays-restaurant-sand-bar","accessed":"2026-10-03"}],"seo":{"meta_title":"Rum Cay, Bahamas: HMS Conqueror Wreck, Hartford Cave & Getting There | TravelWell","meta_description":"Rum Cay: the 1861 HMS Conqueror wreck, Hartford Cave petroglyphs, Grand Canyon wall dives, Port Nelson, and the weekly flight and mail boat from Nassau.","slug":"rum-cay-bahamas","primary_keyword":"Rum Cay Bahamas","jsonld_type":"TouristDestination"},"hero":{"query":"Rum Cay Bahamas"}}'::jsonb, 9),
  ('san-salvador-bahamas', '11C', 'San Salvador', 'Bahamas', 'Where Columbus came ashore', 'future', 'verified', 'mountainValley', 'Bahamas', '{"diveglobal","culture","tropical","yacht","family"}', '{"historic","secluded","remote","tropical","coastal"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/bahamas","verified":"2026-10-03"},"jewels":[{"name":"Columbus Monument, Long Bay","source":"https://www.bahamas.com/vendor/columbus-monument","accessed":"2026-10-03","si":["culture","senior","diveglobal"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"This monument to Columbus landfall is located at Long Bay, so named for Columbus long boat. This is the point where he came ashore. A monument placed on the floor of the ocean in Long Bay marks the exact spot where Columbus dropped anchor on October 12th, 1492. On the beach, a simple white cross commemorates the first land discovered in the West Indies.\" The cross, \"erected by Columbian historian Ruth D. Wolper and the people of San Salvador in 1956, is the most photographed spot on the island.\"","commission_status":"none","booking_route":"none needed - public monument on the beach"},{"name":"Riding Rock Resort & Marina","source":"https://www.ridingrock.com/about-riding-rock-resort/","accessed":"2026-10-03","si":["diveglobal","tropical","group"],"commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":2,"blurb":"\"Built, owned and operated by the William''s family since the 1960''s\"; 22 rooms (18 deluxe in a two-storey building, 4 oceanfront in a single-storey one), \"custom designed for dive travelers, with all of the diving facilities close at hand\". Published 2026 all-inclusive dive packages run from $1,051 (5 days, quad) to $2,711 (8 days, single), including \"Accommodations, meals, San Salvador Airport transfers to/from the resort and all taxes\" (https://www.ridingrock.com/rates-package/, accessed 2026-10-03).","commission_status":"unknown","booking_route":"phone/email only (800.272.1492, 242.331.2631, reservations@RidingRock.com) plus an online enquiry form"},{"name":"Club Med Columbus Isle","source":"https://www.clubmed.us/r/columbus-isle/y","accessed":"2026-10-03","si":["tropical","diveglobal","romance","sailing","family"],"commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat","activities"],"draw_rank":3,"blurb":"An all-inclusive resort on 89 acres; the package covers \"accommodations, unlimited gourmet dining and drinks (alcoholic and non-alcoholic), and access to 25+ included activities\" including sailing, snorkelling and paddleboarding; rooms are \"brightly coloured, heritage-style bungalows with charming Creole design touches\". Scuba diving is extra, with a diving doctor on site; Junior Club Med is named for July-August.","commission_status":"commissioned","booking_route":"own website booking or +1 (888) 932-2582; travel advisors book through the Club Med Travel Advisors portal (cmta.pro.clubmed)"},{"name":"Guanahani Divers","source":"https://www.ridingrock.com/bahamas-diving/","accessed":"2026-10-03","si":["diveglobal","ocean","wildlife"],"commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":4,"blurb":"Riding Rock''s dive operation: \"Both boats are suitable for 20 divers\"; \"Scalloped Hammerheads being a favorite with visiting divers\", \"regularly seen in our waters in the cooler winter months\"; extra boat dives \"$50.00 per dive, provided we have a minimum of 6 divers\". Its site guide names 20 sites, among them Telephone Pole (\"photographed since 1974\"), Devil''s Claw''s double wall and Runway 10, where hammerheads are occasionally seen (https://www.ridingrock.com/san-salvador-dive-sites/, accessed 2026-10-03).","commission_status":"unknown","booking_route":"with the resort: 800.272.1492 or reservations@RidingRock.com; dives are bundled into Riding Rock''s dive packages"},{"name":"Dixon Hill Lighthouse","source":"https://www.bahamas.com/vendor/dixon-hill-lighthouse","accessed":"2026-10-03","si":["culture","senior","family"],"tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":5,"blurb":"\"Built in 1887 on a former plantation owned by John Dixon, this lighthouse is still occupied and operated by lighthouse keepers who refuel the 400,000 candle powered lighthouse by hand every 2 hours and 15 minutes.\" Listed phone (242) 331-2227.","commission_status":"unknown","booking_route":"none listed - bahamas.com gives a phone number, (242) 331-2227, and no admission"},{"name":"Grotto Beach, Sandy Point","source":"https://www.bahamas.com/islands/san-salvador","accessed":"2026-10-03","si":["tropical","romance"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"Named first under \"Find A Sandy Stretch\" on the official island page: \"Grotto Beach at Sandy Point\". Sandy Point Cave and Double Cave dive sites lie off this coast (https://myoutislands.com/bahamas-diving/san-salvador-diving, accessed 2026-10-03).","commission_status":"none","booking_route":"none needed - public beach"},{"name":"Great Lake National Park","source":"https://www.bahamas.com/plan-your-trip/things-to-do/the-great-lake-preserve","accessed":"2026-10-03","si":["wildlife","culture"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"San Salvador is known as ''The Land of Lakes''. In the center of the island is the Great Lake, which served as the major means of transportation in days past. This is a protected body of water, in order to preserve its natural pristine wonder for future generations.\"","commission_status":"none","booking_route":"none needed - protected public lake"},{"name":"Riding Rock Marina","source":"https://www.ridingrock.com/riding-rock-marina-2/","accessed":"2026-10-03","si":["yacht","sailing"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":8,"blurb":"\"Twenty-five slips are available, accommodating boats up to 160 feet with advanced notice.\" \"Draft at the marina entrance is 8 feet at low tide and 12 feet at high tide.\" \"The fuel dock is open all year for diesel, gasoline and ice\", 8 a.m. to 5 p.m. Sunday-Friday. Dockage published at $3.00 per foot per day.","commission_status":"unknown","booking_route":"phone/email only (800.272.1492, 242.331.2631, reservations@RidingRock.com)"},{"name":"Odyssey III deep-sea fishing charter (Riding Rock)","source":"https://www.ridingrock.com/fishing/","accessed":"2026-10-03","si":["ocean","sports","group"],"commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":9,"blurb":"Riding Rock''s 28-foot charter boat: \"1/2 Day (4 Hours) $800\" and \"Full Day (8 Hours) $1200\" per vessel, maximum 5 persons; \"Tackle, bait, and water are provided\"; targets Blue Marlin, Wahoo, Dolphin, Kingfish and Tuna, and the resort encourages \"catch and release sport fishing in an effort towards conservation\".","commission_status":"unknown","booking_route":"phone/email only (800.272.1492, 242.331.2631, reservations@RidingRock.com)"},{"name":"Guanahani Beach Club Resort","source":"https://www.bahamas.com/hotels/guanahani-beach-club-resort","accessed":"2026-10-03","si":["tropical","sailing","adventure","romance"],"commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat","activities"],"draw_rank":10,"blurb":"\"Our secluded property is located on the southeast coast of San Salvador, just 15 minutes from the San Salvador International\" airport; private villas, the Patio Restaurant Bar, a Surf & Sail Center with catamaran sailing, diving, kayaking and kitesurfing, at Sunrise Road, Snowy Bay, Sandy Point. Its own site (guanahanibeachclub.com) returned only a bot check when read, so this listing is the source.","commission_status":"unknown","booking_route":"phone/email only ((242) 452-0438, info@guanahanibeachclub.com, Ms. Elena Sparta) per the official listing"},{"name":"The Chicago Herald Monument","source":"https://www.bahamas.com/vendor/chicago-herald-monument","accessed":"2026-10-03","si":["culture","senior"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"The 1892 Worlds Fair, held in Chicago, celebrated the 400th anniversary of the discovery of the New World. In 1891, the Chicago Herald, an American newspaper, erected this sphere (hewn from native limestone) in commemoration of Columbus landfall.\"","commission_status":"none","booking_route":"none needed - public monument"},{"name":"Snow Beach and Snow Bay","source":"https://www.bahamas.com/islands/san-salvador","accessed":"2026-10-03","si":["tropical","sailing"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"Named on the official island page under \"Find A Sandy Stretch\" (Snow Beach) and \"Drop Anchor In A Pristine Bay\" (\"Dim Bay, Long Bay, and Snow Bay\"). Guanahani Beach Club lists its address as Snowy Bay, Sandy Point (https://www.bahamas.com/hotels/guanahani-beach-club-resort, accessed 2026-10-03).","commission_status":"none","booking_route":"none needed - public beach and bay"},{"name":"Bonefish Bay Beach","source":"https://www.bahamas.com/islands/san-salvador","accessed":"2026-10-03","si":["tropical","family"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"Named on the official island page under \"Find A Sandy Stretch\". Club Med''s Christopher Restaurant gives its address as Bonefish Bay, Cockburn Town (https://www.bahamas.com/vendor/christopher-restaurant, accessed 2026-10-03), and the Frasgate wreck lies \"off Bonefish Bay\" (https://myoutislands.com/bahamas-diving/san-salvador-diving, accessed 2026-10-03).","commission_status":"none","booking_route":"none needed - public beach"},{"name":"Watling''s Blue Hole","source":"https://www.bahamas.com/natural-wonders/watlings-blue-hole","accessed":"2026-10-03","si":["adventure","wildlife"],"tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"Watling''s Blue Hole, southwestern San Salvador Island\" - \"a popular spot among researchers interested in the categories of soluble rocks in The Bahamas\": large water-filled, subcylindrical voids that extend well below sea level.","commission_status":"none","booking_route":"none listed - a natural site; the official page names no access fee or operator"},{"name":"Gerace Research Centre","source":"https://www.bahamas.com/plan-your-trip/things-to-do/the-gerace-research-center","accessed":"2026-10-03","si":["deepdive","wildlife","group"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"\"The Gerace Research Center, formerly the Bahamian Field Station, occupies an old U.S. Navy base at Graham''s Harbour on San Salvador''s northern coast\", working in archaeology, biology, geology and marine science for over 50 years and supporting conservation of the endangered San Salvador rock iguana. Its own site lists \"separate housing for undergraduates, graduate students, faculty and researchers\", field courses, and \"SCUBA tanks are available for rent\" (https://www.geraceresearchcentre.com/facilities.html, accessed 2026-10-03).","commission_status":"unknown","booking_route":"phone/email only ((242) 331-2520, grcsansal@gmail.com); facilities serve students, faculty and researchers"},{"name":"Columbus Tavern Restaurant and Bar","source":"https://www.bahamas.com/vendor/columbus-tavern-restaurant-and-bar","accessed":"2026-10-03","si":["culinary"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":16,"blurb":"\"Located in the heart of North Victoria Hill, we specialize in native Bahamian dishes, but we are widely known for our delicious melt-in-ya-mouth Cracked Conch.\" Queen''s Highway, North Victoria Hill; (242) 331-2612.","commission_status":"unknown","booking_route":"phone only ((242) 331-2612)"},{"name":"Riding Rock Inn Restaurant and Driftwood Lounge","source":"https://www.bahamas.com/plan-your-trip/restaurants/riding-rock-inn-restaurant-and-bar","accessed":"2026-10-03","si":["culinary","diveglobal"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":17,"blurb":"\"Our restaurant specializes in American and Bahamian cuisine, with an accent on fresh fish. We offer a friendly, casual atmosphere and a magnificent ocean view.\" Queen''s Highway, Cockburn Town; (242) 331-2631. Breakfast 7:30-9:00 am, lunch 12:30-2:00 pm, dinner 6:30-8:30 pm; meals \"can be purchased a la carte\" (https://www.ridingrock.com/about-riding-rock-resort/, accessed 2026-10-03).","commission_status":"unknown","booking_route":"phone only ((242) 331-2631)"},{"name":"Christopher Restaurant (Club Med Columbus Isle)","source":"https://www.bahamas.com/vendor/christopher-restaurant","accessed":"2026-10-03","si":["culinary","family"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":18,"blurb":"\"Located at the Club Med Resort, buffet style restaurant\" serving breakfast, lunch and dinner with rotating nightly themes - Bahamian, Mediterranean, Asian, French, American and Mexican. Bonefish Bay, Cockburn Town; (242) 331-2000.","commission_status":"unknown","booking_route":"included in the Club Med all-inclusive stay; listed phone (242) 331-2000"},{"name":"The Sands Hotel Restaurant and Bar","source":"https://www.bahamas.com/plan-your-trip/restaurants/sands-hotel-restaurant-and-bar","accessed":"2026-10-03","si":["culinary"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":19,"blurb":"\"The restaurant at The Sands Residence offers a variety of tantalizing Bahamian dishes in an intimate setting.\" Queen''s Highway, Cockburn Town; (242) 331-1018.","commission_status":"unknown","booking_route":"phone only ((242) 331-1018)"},{"name":"Paradis Restaurant & Bar","source":"https://www.bahamas.com/plan-your-trip/restaurants/paradis-restaurant--bar","accessed":"2026-10-03","si":["culinary"],"commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":20,"blurb":"\"Specializing in Bahamian cuisine, Paradis Restaurant & Bar offers a wide variety of scrumptious down-home dishes – from fresh Grouper Fingers to Jerk Chicken.\" Columbus Plaza, Queen''s Highway, Bonefish Bay; (242) 331-2400.","commission_status":"unknown","booking_route":"phone only ((242) 331-2400)"},{"name":"San Sal Kitesurfing","source":"https://www.bahamas.com/hotels/guanahani-beach-club-resort","accessed":"2026-10-03","si":["adventure","sports","ocean"],"commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":21,"blurb":"Named on the official listing for Guanahani Beach Club Resort as the provider of kitesurfing courses and equipment rentals at the resort''s Surf & Sail Center, Snowy Bay, Sandy Point. No own page for San Sal Kitesurfing was read.","commission_status":"unknown","booking_route":"through Guanahani Beach Club: (242) 452-0438 or info@guanahanibeachclub.com"}],"faq":[{"q":"How do I get to San Salvador, Bahamas?","a":"By air. The official tourism site says \"San Salvador Airport (ZSA)\" is \"the island''s only airport\" and \"welcomes international and domestic arrivals\". No ferry or mail-boat service to San Salvador is described on the official getting-here page.","source":"https://www.bahamas.com/islands/san-salvador","accessed":"2026-10-03"},{"q":"Which airlines fly to San Salvador, Bahamas?","a":"Wikipedia''s airport page lists Bahamasair to \"Deadman''s Cay, Miami, Nassau, Rock Sound\", Air Canada Rouge to \"Montréal–Trudeau\" and Air Caraïbes \"Seasonal: Paris–Orly\". Check the carrier for current schedules; none was read on a carrier''s own page.","source":"https://en.wikipedia.org/wiki/San_Salvador_Airport","accessed":"2026-10-03"},{"q":"What is the San Salvador, Bahamas airport code?","a":"ZSA. The official site names it \"San Salvador Airport (ZSA)\"; its ICAO code is \"MYSM\" (https://en.wikipedia.org/wiki/San_Salvador_Airport, accessed 2026-10-03).","source":"https://www.bahamas.com/islands/san-salvador","accessed":"2026-10-03"},{"q":"What is San Salvador, Bahamas known for?","a":"Columbus''s landfall and its diving. The official site calls it \"a unique island with sparkling lakes, historic monuments, secluded beaches, and dive sites\", with \"50+ Dive Sites\", and says Columbus''s landing is marked by \"a stone cross on San Salvador''s Long Bay\".","source":"https://www.bahamas.com/islands/san-salvador","accessed":"2026-10-03"},{"q":"What is there to do in San Salvador, Bahamas?","a":"The official island page lists beaches (\"Grotto Beach at Sandy Point, Bonefish Bay Beach, and Snow Beach\"), bays to anchor in (\"Dim Bay, Long Bay, and Snow Bay\"), \"50+ Dive Sites\" including \"Devil''s Claw, Vicky''s Reef, and Runway 10\", fishing for \"blue marlin, wahoo, dolphin, kingfish, and tuna\", the Columbus landfall cross, the Gerace Research Centre, Great Lake National Park and Watling''s Blue Hole.","source":"https://www.bahamas.com/islands/san-salvador","accessed":"2026-10-03"},{"q":"Where should I stay in San Salvador, Bahamas?","a":"The official site says lodging ranges from \"all-inclusive luxury villas to fully furnished beachfront cottages\". The properties read for this dossier are Club Med Columbus Isle (all-inclusive), Riding Rock Resort & Marina (a dive resort with 22 rooms) and Guanahani Beach Club Resort (private villas at Snowy Bay, Sandy Point).","source":"https://www.bahamas.com/islands/san-salvador","accessed":"2026-10-03"},{"q":"Is there a Club Med in San Salvador, Bahamas?","a":"Yes: Club Med Columbus Isle, an all-inclusive resort on 89 acres. The package covers \"accommodations, unlimited gourmet dining and drinks (alcoholic and non-alcoholic), and access to 25+ included activities\"; scuba diving is extra.","source":"https://www.clubmed.us/r/columbus-isle/y","accessed":"2026-10-03"},{"q":"Are there all-inclusive resorts in San Salvador, Bahamas?","a":"Club Med Columbus Isle is all-inclusive. Riding Rock Resort & Marina also sells \"All Inclusive Dive Vacation Packages\" and non-diver packages that include \"Accommodations, meals, San Salvador Airport transfers to/from the resort and all taxes\" but exclude alcoholic drinks, sodas, bottled water and gratuities (https://www.ridingrock.com/rates-package/, accessed 2026-10-03).","source":"https://www.clubmed.us/r/columbus-isle/y","accessed":"2026-10-03"},{"q":"How big is San Salvador, Bahamas?","a":"San Salvador Island covers \"163 km2 (63 sq mi)\". The official tourism site adds that the island is \"the exposed peak of a 15,000 ft mountain\" (https://www.bahamas.com/islands/san-salvador, accessed 2026-10-03).","source":"https://en.wikipedia.org/wiki/San_Salvador_Island","accessed":"2026-10-03"},{"q":"What is the population of San Salvador, Bahamas?","a":"\"The 2022 census recorded 824 residents\", per Wikipedia''s island article.","source":"https://en.wikipedia.org/wiki/San_Salvador_Island","accessed":"2026-10-03"}],"seo":{"meta_title":"San Salvador, Bahamas: Columbus Landfall, Wall Diving & Where to Stay | TravelWell","meta_description":"Columbus''s 1492 landfall at Long Bay, the 1887 Dixon Hill Lighthouse, 50+ dive sites, Club Med Columbus Isle and Riding Rock, reached via ZSA airport.","slug":"san-salvador-bahamas","primary_keyword":"San Salvador Bahamas","jsonld_type":"TouristDestination"},"hero":{"query":"San Salvador Bahamas"}}'::jsonb, 10),
  ('abaco-bahamas', '11C', 'Abaco', 'Bahamas', 'The Bahamas'' sailing capital', 'live', 'verified', 'tropicalBeach', 'Bahamas', '{"tropical","sailing","ocean","sports","culture","yacht"}', '{"tropical"}', '{"premier","ultra"}', null, null, '{"key_facts":["Sailing hub: Marsh Harbour = primary charter base (Moorings/Sunsail/Dream)","Top nodes: Hope Town (Elbow Cay), Green Turtle Cay; sheltered Sea of Abaco","Hope Town lighthouse (1863, red-and-white, visible 23 mi)","Dorian (Cat-5, 2019) devastated Abaco; recovery well advanced - fleets active","Active 2026 charter market; no dive liveaboard; malaria none; hurricane Jun-Nov peak Aug-Oct"],"safety":{"emergency":"911 / 919","hospital":"Marsh Harbour clinic/hospital (post-Dorian rebuilt); Nassau referral","malaria":"NONE","yellow_fever":"only if arriving from an endemic country","hurricane":"Jun-Nov, peak Aug-Oct (Dorian 2019 ground-zero)","firearms_ammo_law":"Bahamas ammo law applies — disclose","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-09-01T16:20:19Z","page_updated":"2026-05-28T17:01:45+01:00","source_country":"bahamas","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":null,"jewels":[{"name":"The Moorings - Abacos yacht charters (Marsh Harbour)","blurb":"base in Marsh Harbour; \"A short, 1-hour flight from multiple Florida airports\"; bareboat, power, skippered and crewed charters; recommended stops Hope Town, Green Turtle Cay (New Plymouth) and Tahiti Beach on Elbow Cay; itineraries of 4 nights, 5 nights and 7 days through Great Guana, Manjack Cay, Green Turtle Cay, Hope Town, Little Harbour, Lynyard Cay and Man-O-War Cay","si":["sailing","yacht","romance","group"],"commission":"operator","wells":["activities","fly","move","stay"],"draw_rank":2,"fit_rules":{"duration":"4 nights, 5 nights or 7 days (https://www.moorings.com/destinations/americas/bahamas/abacos-yacht-charters/itinerary, 2026-10-02)","before":"sailing resume for bareboat (carried from output/abaco-bahamas.md, accessed 2026-07-02; not restated on the itinerary page read 2026-10-02)","after":"none (carried)","pairs_with":"Hope Town, Green Turtle Cay, Tahiti Beach (destination page, 2026-10-02)","time_season":"December through April for steady trade winds (destination page, 2026-10-02)"},"tier_absent_reason":"not-established","source":"https://www.moorings.com/destinations/americas/bahamas/abacos-yacht-charters","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Elbow Reef Lighthouse (Hope Town, Elbow Cay)","blurb":"\"the only active and manned lightstation in the world that has not been electrified\" - \"The lens is hand-wound by a keeper and fueled by kerosene\"; lightstation built circa 1863; \"open Monday to Saturday from 9:00am - 5:00pm. CLOSED ON SUNDAY.\" The Moorings adds that it \"can be seen from 23 miles away\"","si":["culture","sailing","family","senior"],"wells":["activities"],"draw_rank":1,"fit_rules":{"duration":"half-day (carried from output/abaco-bahamas.md, Moorings source accessed 2026-07-02)","before":"none (carried)","after":"none (carried)","pairs_with":"a charter stop in Hope Town (carried; Hope Town is a Moorings recommended stop, re-checked 2026-10-02)","time_season":"Monday to Saturday 9:00am-5:00pm, closed Sunday (Society page, 2026-10-02)"},"tier_absent_reason":"not-sold","source":"https://elbowreeflighthousesociety.com/","accessed":"2026-10-02","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Tahiti Beach (Elbow Cay)","blurb":"the Ministry of Tourism: reached by bike, boat or foot, with a sandbar at low tide; The Moorings names it a recommended swimming and snorkelling stop","si":["tropical","family","romance","sailing"],"wells":["activities","move"],"draw_rank":12,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/islands/abaco","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text","commission":"entry non-commissionable (curated) - pair with a beach stay or boat day","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a beach - free; the stay and a boat day are the paid route"},{"name":"Pelican Cays Land and Sea Park","blurb":"Bahamas National Trust park established 1972, protecting \"2,100 acres of extensive coral reefs\" 8 miles north of Cherokee Sound; \"spectacular snorkeling and diving\"; \"More than 170 species have been documented\"; \"Only accessible by boat\"; \"Daytime/snorkel moorings available for use. Fees will be applied soon.\"","si":["ocean","diveglobal","wildlife","sailing"],"wells":["activities","move"],"draw_rank":3,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/abaco/pelican-cays-land-and-sea-park/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Abaco Lodge (the Marls)","blurb":"\"the only fly-fishing operation with direct access to the vast Marls of Abaco, one of the most sought-after bonefishing destinations in the world\"; published packages from \"3 Nights / 2 Days Fishing $ 4,250 per person\" (Fall 2026) to \"7 Nights / 6 Days Fishing $ 8,350 per person\" (Peak 2027), shared room and boat; includes \"Lodging, meals, open bar, guided fishing, fishing license, transportation between Abaco Lodge and Marsh Harbour and loaner fishing equipment\"; excludes \"Airfares, flies, gratuities and government taxes\"","si":["sports","ocean","group"],"commission":"operator","wells":["activities","eat","gear","move","stay"],"draw_rank":4,"tier_absent_reason":"not-established","source":"https://www.abacolodge.com/rates","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Regattas in The Abacos 2026","blurb":"\"an unforgettable eight-day sailing event that combines exciting races with lively island parties each evening\", June 20-28, 2026, through Green Turtle Cay, Great Guana Cay, Marsh Harbour, Elbow Cay and Little Harbour; classes Spinnaker, Non-spinnaker, MotherTub and MultiTub","si":["sailing","spectator","entertainment","yacht"],"commission":"venue","wells":["activities","move"],"draw_rank":5,"tier_absent_reason":"does-not-compete","source":"https://regattasintheabacos.com","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Green Turtle Club Resort & Marina","blurb":"on Green Turtle Cay, \"an island three miles long, accessible only by boat\"; marina in White Sound with \"7'' mean low tide\"; the Dollar Bar and the Club Restaurant, where Chef Michael Howell cooks \"World/Caribbean fusion cuisine\" with \"freshly caught Abaco seafood\"","si":["tropical","romance","sailing","culinary"],"commission":"hotel","wells":["activities","eat","move","stay"],"draw_rank":6,"tier_absent_reason":"not-established","source":"https://www.greenturtleclub.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Hope Town Inn & Marina","blurb":"a 15-acre private estate on Hope Town''s western side next to the Elbow Reef Lighthouse; hotel rooms with harbour views and villas including Oleander Villa and Wild Orchid Villa; dockage for vessels up to 120 feet; hosts the Elbow Reef Classic fishing tournament each May; MarinaLife 2024 Readers'' Choice winner","si":["tropical","sailing","romance","yacht"],"commission":"hotel","wells":["activities","eat","stay"],"draw_rank":7,"tier_absent_reason":"not-established","source":"https://www.hopetownmarina.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Abaco Beach Resort (Marsh Harbour)","blurb":"\"40 beachfront acres\" with 96 beachfront rooms and suites with ocean views and private patios; The Bistro (Bahamian with Asian and Mediterranean influences) and The Terrace at Marinaville; Cruise Abaco''s charter fleet is based at its Boat Harbour Marina","si":["tropical","family","yacht","sailing"],"commission":"hotel","wells":["activities","eat","move","stay"],"draw_rank":8,"tier_absent_reason":"not-established","source":"https://www.abacobeachresort.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bluff House Beach Resort & Marina","blurb":"\"12 tropical acres of palms and pine\" on Green Turtle Cay between White Sound and the Sea of Abaco, \"the first and is now the oldest resort\" in the Out Islands; eight hotel suites plus cottages and villas; 40-slip marina with 7 feet at mean low water; the Boathouse Bar & Restaurant","si":["tropical","family","sailing","group"],"commission":"hotel","wells":["activities","eat","stay"],"draw_rank":9,"tier_absent_reason":"not-established","source":"https://www.bluffhouse.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"IYC - Abaco crewed yacht charter","blurb":"\"a 120-mile boomerang-shaped chain of islands and cays\"; \"December to April, the peak cruising season, offers the most favourable conditions\"; highlights the swimming pigs at No Name Cay, Pelican Cays Land and Sea Park, Hope Town, Great Guana Cay and Treasure Cay''s crescent beach, and the Albert Lowe museum in New Plymouth","si":["yacht","ultra","romance"],"commission":"operator","wells":["activities","stay","move"],"draw_rank":10,"tier_absent_reason":"not-established","source":"https://iyc.com/abacos/","accessed":"2026-10-02"},{"name":"Cruise Abaco (Marsh Harbour)","blurb":"\"the only boutique sailing operation in the Abacos\", based at Boat Harbour Marina, Marsh Harbour; sailing and power catamarans and monohulls of 40 to 50 feet; bareboat or \"Captained by Day, Bareboat by Night\"; operates year-round","si":["sailing","yacht","family"],"commission":"operator","wells":["activities","move","shop","stay"],"draw_rank":11,"tier_absent_reason":"not-established","source":"https://www.cruiseabaco.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Albury Brothers boat builders (Man-O-War Cay)","blurb":"a two-century boat-building tradition: \"Some companies build 30 boats a month, the Albury Brothers, they build 8 for the entire year\"; Albury women weave handbags from sail material; Man-O-War Cay is \"reachable by ferry via Marsh Harbour\" and \"one of the earliest colonial settlements in The Abacos\"","si":["culture","sailing","senior"],"commission":"venue","wells":["activities","move","shop"],"draw_rank":13,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/experiences/albury-brothers-abacos","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Abaco National Park (South Abaco)","blurb":"established 1994 \"to protect the northern breeding grounds for The Bahama Parrot\", which nests \"in underground cavities in the pine forest\"; the population rose from about 1,500 birds in 1986 to 8,900 after a 2009 predator control programme; 20,500 acres of Caribbean pine and coppice forest on the park page (the BNT Abaco index page says 22,500)","si":["wildlife","hiking","senior"],"wells":["activities"],"draw_rank":14,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/abaco/abaco-national-park/","accessed":"2026-10-02","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Brendal''s Dive Center (Green Turtle Cay)","blurb":"\"one or two dives per day from 10 to 100 feet\", snorkelling, island-hopping and a \"Wild Dolphin Encounter Day\"; \"Explore coral catacombs and sparkling sand channels or dive a fascinating wreck\"; kayak, paddleboard, golf cart and bike rentals; Brendal Stevens has instructed \"OVER 5000 Students\"","si":["diveglobal","ocean","family","wildlife"],"commission":"operator","wells":["activities","gear","move"],"draw_rank":15,"tier_absent_reason":"does-not-compete","source":"https://www.brendal.com/","accessed":"2026-10-02"},{"name":"Pete''s Pub & Gallery (Little Harbour)","blurb":"\"a classic beach restaurant/pub and the only working sculpture foundry in the Bahamas\"; the Ministry of Tourism lists the Johnston Art Gallery & Foundry beside it. Its own site carries no current hours or open-status statement, so check before going","si":["culture","culinary","sailing"],"commission":"venue","wells":["activities","eat","shop"],"draw_rank":16,"tier_absent_reason":"does-not-compete","source":"https://www.petespubandgallery.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Nipper''s Beach Bar & Grill (Great Guana Cay)","blurb":"on Great Guana Cay, +1 242 365 5111. Its homepage shows menu and contact sections but no hours or open-status statement, so check before going","si":["entertainment","tropical","culinary"],"commission":"venue","wells":["activities","eat"],"draw_rank":17,"tier_absent_reason":"does-not-compete","source":"https://www.nippersbar.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"Cap''n Jack''s Restaurant and Bar (Hope Town)","blurb":"\"Sitting right on the water in Hope Town harbor\" - \"homestyle Bahamian cooking, delicious pub fare, refreshing cocktails\"; bar 10:30 a.m. to closing, kitchen 11:00 a.m. to 9:00 p.m., Monday-Saturday","si":["culinary","sailing","family"],"commission":"venue","wells":["activities","eat"],"draw_rank":18,"tier_absent_reason":"does-not-compete","source":"https://www.capnjackshopetown.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Abaco Inn (Elbow Cay)","blurb":"on Elbow Cay where \"brilliant white sands\" meet the Atlantic on one side and the Sea of Abaco on the other; cottages, ocean-view rooms, Hill Top Cottages and Sunset Point Villas with private docks; the Abaco Inn Restaurant serves seared tuna, conch chowder and coconut-fried lobster; hosts weddings","si":["romance","tropical","culinary"],"commission":"hotel","wells":["activities","eat","stay"],"draw_rank":19,"tier_absent_reason":"not-established","source":"https://www.abacoinn.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Firefly Sunset Resort (Hope Town)","blurb":"\"five beautiful vacation cottages and villas designed for couples, families, and friends\", including the Mint To Be honeymoon suite with a private plunge pool; Firefly Bar & Grill open seven days, breakfast 8-11am; after Dorian it restored power and rebuilt its dock, outdoor bar and dining area, and \"Two villas were lost\"","si":["romance","tropical","family"],"commission":"hotel","wells":["activities","eat","stay"],"draw_rank":20,"tier_absent_reason":"not-established","source":"https://www.fireflysunsetresort.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Albert Lowe Museum (New Plymouth, Green Turtle Cay)","blurb":"\"The first historic museum in the Bahamas\" - photographs, paintings, sculptures, model ships, documents and quilts; \"the front room of the Albert Lowe Museum has been repaired, restored and reopened post-Hurricane Dorian\" (update dated January 1, 2024); hours vary weekly and are posted on its Facebook page","si":["culture","senior","family"],"commission":"venue","wells":["activities","stay"],"draw_rank":21,"tier_absent_reason":"not-sold","source":"https://www.albertlowemuseum.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Fowl Cays National Park (North Abaco)","blurb":"established 2009, \"valuable coral reef, seagrass beds, rocky shore and sandy bottom habitats\"; \"Only accessible by boat\"; daytime snorkel moorings, \"Fees will be applied soon\"; \"there is no one on guard\"","si":["ocean","diveglobal","wildlife"],"wells":["activities","move"],"draw_rank":22,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/abaco/fowl-cays-national-park/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Hope Town Sailing Club races (Sea of Abaco)","blurb":"\"a private Club licensed in the Bahamas\" founded 1964; 2027 races include the Yeardley Smith Trophy January 16, Woman''s Regatta January 24, Founders Cup February 24 and Last Mast Blast March 27, 2027; \"Guests of members, may attend with the member\" the Saturday \"Stand up at the Club House\"","si":["sailing","spectator","sports"],"commission":"venue","wells":["activities","move"],"draw_rank":23,"tier_absent_reason":"not-sold","source":"https://www.hopetownsailingclub.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Northern Breezes Sailing - Abacos flotilla","blurb":"2026 flotillas November 28-December 5 and December 5-12, or both weeks November 28-December 12; the operator''s own Dorian read: \"the region is quickly returning to its pre-hurricane conditions, with extensive rebuilding on most cays\"","si":["sailing","group"],"commission":"operator","wells":["activities","move","stay"],"draw_rank":24,"tier_absent_reason":"not-established","source":"http://northernbreezessailing.com/index.php/abacos-bahamas-flotilla/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Sea Spray Resort & Marina (White Sound, Elbow Cay)","blurb":"full-service marina, bars and restaurants on White Sound, residences for short-term stays; Thursday night live music or DJ, game night and karaoke; fishing, snorkelling and boating","si":["sailing","tropical","entertainment"],"commission":"hotel","wells":["activities","eat","stay"],"draw_rank":25,"tier_absent_reason":"not-established","source":"https://www.seasprayresort.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Tranquil Turtle Beach Bar (Bluff House, Green Turtle Cay)","blurb":"Bluff House''s beachfront bar, which its page says was rated \"#6 out of the Top 25 Beach Bars in the Caribbean\"","si":["tropical","entertainment","culinary"],"commission":"venue","wells":["activities","eat"],"draw_rank":26,"tier_absent_reason":"does-not-compete","source":"https://www.bluffhouse.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"Bridget''s Rum Bar & Restaurant (Hope Town Inn & Marina)","blurb":"breakfast, lunch and dinner of local and American cuisine, with \"an extensive rum selection\" at the bar","si":["culinary","sailing"],"commission":"venue","wells":["activities","eat","stay"],"draw_rank":27,"tier_absent_reason":"does-not-compete","source":"https://www.hopetownmarina.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Treasure Sands Club (Treasure Cay)","blurb":"fine dining at Treasure Sands and casual Sunset Pizza. 🔴 Seasonally closed on 2026-10-02: Sunset Pizza reopens October 19th (Monday-Friday 3PM-9PM, Saturday-Sunday 12PM-9PM); Treasure Sands reopens December 20th with Art Market, Christmas and New Years events","si":["culinary","romance","tropical"],"commission":"venue","wells":["activities","eat"],"draw_rank":28,"tier_absent_reason":"does-not-compete","source":"https://www.treasuresandsclub.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Schooner Bay (South Abaco)","blurb":"\"a private village centered around a natural harbour\" in a \"golf-cart- and pedestrian-friendly village setting\"; vacation rentals and a \"3-night, 4-day\" Discovery Stay for prospective buyers; bonefishing and water sports","si":["tropical","family","sports"],"commission":"hotel","wells":["activities","gear","move","stay"],"draw_rank":29,"tier_absent_reason":"not-established","source":"https://www.schoonerbaybahamas.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"G&L Ferry Service (The Crossing, Marsh Harbour)","blurb":"runs \"Marsh Harbour to Hope Town, Man-O-War and Guana Cay\" from The Crossing, Marsh Harbour, with a dock on Front Street, Guana Cay; \"NO RESERVATIONS NEEDED FOR SCHEDULED RUNS!\" - \"GET YOUR TICKETS AT THE DOCK\"; schedule published as a linked document","si":["ocean","family","senior"],"commission":"operator","wells":["activities","move"],"draw_rank":30,"tier_absent_reason":"does-not-compete","source":"https://gandlferry.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Albury''s Ferry Service (Marsh Harbour)","blurb":"\"Albury''s Ferry Service, Marsh Harbour, Abaco, Bahamas\" - ferry service and private charters, adding adventure tours including \"Big O''s and the pigs\"; announces a merger with GNL Transportation and points to the GNL ticketed schedule","si":["ocean","family","tropical"],"commission":"operator","wells":["move","activities"],"draw_rank":31,"tier_absent_reason":"does-not-compete","source":"https://alburysferryservice.com/","accessed":"2026-10-02"},{"name":"Wyannie Malone Historical Museum (Hope Town)","blurb":"Hope Town''s maritime heritage - pirates, shipbuilding, wrecks, period rooms and photographs. 🔴 Its own page on 2026-10-02: \"Currently undergoing repairs. Opening date will be announced when complete.\" Listed admission $5 adults, $2 children 5-14","si":["culture","senior"],"commission":"venue","wells":["activities","stay"],"draw_rank":32,"tier_absent_reason":"not-sold","source":"https://www.hopetownmuseum.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"The Abaco Club on Winding Bay","blurb":"a 500-acre private club with \"the #1 golf course in The Bahamas\", a Scottish-style links that hosts the Korn Ferry Tour''s Bahamas Great Abaco Classic. ⛔ \"The Abaco Club is a private club community reserved exclusively for our homeowners and members. Home rentals are only available to members within the Southworth club portfolio.\"","si":["golf","spectator","ultra"],"commission":"hotel","wells":["activities","gear","move"],"draw_rank":33,"tier_absent_reason":"not-sold","source":"https://theabacoclub.com/","accessed":"2026-10-02","wells_basis":"full pass 2026-10-05, additive — text"}],"faq":[{"q":"What is worth doing in Abaco?","a":"Abaco bareboat/crewed sailing charter — cay-hopping the sheltered Sea of Abaco.","source":"https://www.moorings.com/destinations/americas/bahamas/abacos-yacht-charters"},{"q":"How do I get to the Abacos from Florida?","a":"By air. Tradewind Aviation runs \"scheduled flights from Stuart and Fort Lauderdale to Marsh Harbour, North Eleuthera, and Nassau through June 1, 2027\". Bahamasair''s homepage shows a Marsh Harbour - West Palm Beach route. The Moorings describes the Sea of Abaco as \"A short, 1-hour flight from multiple Florida airports.\"","source":"https://www.flytradewind.com/","accessed":"2026-10-02"},{"q":"What is the name of the Abaco airport?","a":"The Ministry of Tourism lists three: Leonard M. Thompson International Airport in Marsh Harbour, Treasure Cay International Airport, and Sandy Point Airport.","source":"https://www.bahamas.com/islands/abaco","accessed":"2026-10-02"},{"q":"What is the best time to visit the Abacos?","a":"For sailing, the charter operators name December to April: IYC calls it \"the peak cruising season\" that \"offers the most favourable conditions\", and The Moorings cites steady trade winds and clear skies. NOAA: \"The Atlantic hurricane season runs from June 1 to November 30\", with the peak on September 10 and \"most activity occurring between mid-August and mid-October.\"","source":"https://iyc.com/abacos/","accessed":"2026-10-02"},{"q":"What is the Abaco ferry schedule?","a":"G&L Ferry Service runs \"Marsh Harbour to Hope Town, Man-O-War and Guana Cay\" from The Crossing in Marsh Harbour and publishes its timetable as a linked schedule document on its site; \"NO RESERVATIONS NEEDED FOR SCHEDULED RUNS!\" and \"GET YOUR TICKETS AT THE DOCK\". Albury''s Ferry Service, now merged with GNL Transportation, points to the same GNL ticketed schedule and takes charters on 242-822-0290.","source":"https://gandlferry.com/","accessed":"2026-10-02"},{"q":"What is there to do in Abaco, Bahamas?","a":"The Ministry of Tourism lists boating and sailing, sport fishing for blue marlin, sailfish and tuna, scuba diving and snorkelling, and island hopping, with sights including the Elbow Reef Lighthouse, Tahiti Beach on Elbow Cay, The Catacombs dive site off Green Turtle Cay, the Johnston Art Gallery & Foundry and Pete''s Pub at Little Harbour, and the colonial towns of Hope Town and New Plymouth.","source":"https://www.bahamas.com/islands/abaco","accessed":"2026-10-02"},{"q":"What is Abaco known for?","a":"In the Ministry of Tourism''s words, \"The Abacos island chain is a boating, fishing, and sailing paradise\" spanning 120 miles, settled by British Loyalists after the American Revolution, with Man-O-War Cay''s boat-building dating to the 1800s. It also says the Goombay Smash drink originated here.","source":"https://www.bahamas.com/islands/abaco","accessed":"2026-10-02"},{"q":"Where should I stay in the Abacos?","a":"The Ministry of Tourism describes \"Beachfront bungalows, luxury villas, and four-star boutique hotels\". By island: Marsh Harbour has Abaco Beach Resort (96 rooms and suites); Elbow Cay has Hope Town Inn & Marina, Abaco Inn, Firefly Sunset Resort and Sea Spray; Green Turtle Cay has Green Turtle Club and Bluff House, \"the first and is now the oldest resort\" in the Out Islands.","source":"https://www.bahamas.com/islands/abaco","accessed":"2026-10-02"},{"q":"Can you stay at the Abaco Club?","a":"Not as a visitor. The club says: \"The Abaco Club is a private club community reserved exclusively for our homeowners and members. Home rentals are only available to members within the Southworth club portfolio.\"","source":"https://theabacoclub.com/","accessed":"2026-10-02"},{"q":"Do you need a passport to go to the Abaco Islands?","a":"The Abacos are part of The Bahamas, so Bahamian entry rules apply. For travellers on a full British citizen passport the FCDO says: \"Your passport must have an ''expiry date'' at least 6 months after the date you plan to leave\", and \"You can usually stay in The Bahamas for up to 30 days without a visa.\" Travellers of other nationalities should read their own government''s advice; it was not read here.","source":"https://www.gov.uk/foreign-travel-advice/bahamas/entry-requirements","accessed":"2026-10-02"}],"seo":{"meta_title":"Abaco Bahamas: Sailing, Cays & Hope Town","meta_description":"Abaco — the Bahamas'' sailing capital. Charter the sheltered Sea of Abaco, cruise Hope Town and Elbow Cay, and hop the Loyalist Out Island cays. When and how.","slug":"abaco-bahamas","primary_keyword":"Abaco Bahamas sailing charter","long_tail":["Hope Town lighthouse Elbow Cay","Sea of Abaco bareboat","Marsh Harbour yacht charter","Green Turtle Cay Bahamas","Abaco sailing"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-02","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-02","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-08-20T14:54:09Z","source_updated":"2026-05-28T17:01:45+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"Yacht/Sailing","status":"future"}],"ultra":null,"source_verified":"2026-07-02","hero":{"query":"Abaco, Bahamas"},"geo":{"lat":26.35,"lng":-77.05},"orbit":[{"id":"andros-bahamas","jewels":3,"si":["diveglobal"]},{"id":"bimini-bahamas","jewels":3,"si":["diveglobal"]},{"id":"eleuthera-bahamas","jewels":3,"si":["tropical","diveglobal","expedition"]},{"id":"exuma-bahamas","jewels":3,"si":["expedition","liveaboard"]},{"id":"grand-bahama-freeport-bahamas","jewels":3,"si":["diveglobal","liveaboard","expedition"]},{"id":"harbour-island-bahamas","jewels":3,"si":["tropical","ultra","culture"]},{"id":"long-island-bahamas","jewels":3,"si":["tropical","expedition","diveglobal"]},{"id":"nassau-paradise-island-bahamas","jewels":3,"si":["romance","diveglobal","liveaboard"]}],"orbit_country":[]}'::jsonb, 11)
insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('andros-bahamas', '11C', 'Andros', 'Bahamas', 'The Bahamas'' wild frontier', 'live', 'verified', 'oceanAerial', 'Bahamas', '{"diveglobal","tropical","adventure","wildlife","romance"}', '{}', '{"premier","ultra"}', null, null, '{"key_facts":["Great Andros Barrier Reef - 124 miles (widely cited 3rd-longest - verify)","Tongue of the Ocean drop-off - deep-trench wall dives + pelagics","Blue holes - tidal freshwater sinkholes; 100+ off South Andros","Small Hope Bay Lodge + Andros Beach Club (land-based dive lodges)","World-class bonefishing; no liveaboard fleet; malaria none; hurricane Jun-Nov peak Aug-Oct"],"safety":{"emergency":"911 / 919","hospital":"local clinics; Nassau referral","malaria":"NONE","yellow_fever":"only if arriving from an endemic country","hurricane":"Jun-Nov, peak Aug-Oct","dive_no_fly":"18-24h (DAN); blue-hole/cave = advanced only","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-09-01T16:20:19Z","page_updated":"2026-05-28T17:01:45+01:00","source_country":"bahamas","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":null,"jewels":[{"name":"Tongue of the Ocean wall dive (Small Hope Bay Lodge)","blurb":"CARRIED from the earlier dossier, re-sourced from a guide site (takeyourbackpack.com) to the operator''s own page: \"stunning wall dives at the edge of the continental shelf\"; \"The Tongue of the Ocean - a deep ocean trench that drops over 6,000 feet - begins right offshore, offering world-class diving without long boat rides.\" Published: one-tank $125, two-tank $150, night/shark dive $125 (minimum 6 divers), boat snorkel $50","si":["diveglobal","ocean","adventure"],"commission":"operator","wells":["activities","move","stay"],"draw_rank":4,"fit_rules":{"duration":"one-tank or two-tank boat dive","before":"certification; PADI or SSI Open Water $300 offered on site","after":"no fly-after rule stated on the page","pairs_with":"Andros Barrier Reef coral formations, blue holes, shark dives","time_season":"not stated on the page"},"tier_absent_reason":"does-not-compete","source":"https://www.smallhope.com/diving","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Andros Beach Club - Blue Hole Tours","blurb":"CARRIED from the earlier dossier (\"Andros blue-hole dive\") and re-read today: \"guided snorkeling and diving tours of the Andros Blue Holes\" including Stargate Blue Hole and El Dorado, \"tidal freshwater blue holes\" on \"a major fault line of blue holes running over 50 miles through South Andros\"; also \"Barb''s Nature Walk and Blue Hole Tour\", a guided hike to inland blue holes. No duration or price on the page","si":["diveglobal","adventure","hiking","ocean"],"commission":"operator","wells":["activities"],"draw_rank":5,"tier_absent_reason":"does-not-compete","source":"https://www.androsbeachclub.com/blue-hole-tours/","accessed":"2026-10-03"},{"name":"Andros Barrier Reef","blurb":"Ministry of Tourism: \"The world''s 3rd largest barrier reef\", \"190 miles long\"; it \"drops to about eight feet on the island side and approximately 6,000 feet in the Tongue of the Ocean.\" CARRIED from the earlier dossier and re-read today: the earlier \"124-mi\" length is the figure Small Hope Bay Lodge still uses; bahamas.com now states 190 miles, and both are quoted rather than reconciled","si":["diveglobal","tropical","ocean","wildlife"],"wells":["activities","stay"],"draw_rank":1,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/natural-wonders/andros-barrier-reef","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Captain Bill''s Blue Hole","blurb":"Ministry of Tourism: \"Just follow the winding trail until you reach a clearing, and you can''t miss Captain Bill''s.\" \"A deck hangs over the water''s edge so, go ahead, jump right in.\" Bahamas National Trust: \"nearly perfectly round\" with \"a depth of 100+ feet\", a gazebo and a staircase into the water; \"No entry fee\" - but the BNT page reads \"Closed temporarily\" on the date read","si":["adventure","tropical","family","hiking"],"wells":["activities"],"draw_rank":2,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/blue-holes-national-park/","accessed":"2026-10-03","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Small Hope Bay Lodge","blurb":"\"a historic, intimate, and eco-friendly resort\", founded 1960, all-inclusive beachfront cabins with \"All Meals and Open Bar\", bikes, kayaks, diving and snorkelling lessons, nature tours and complimentary babysitting; published all-inclusive daily rates: adult $375 low season, $425 high season, kids (2-12) $135, under 2 free; 855-841-6966, info@smallhope.com","si":["diveglobal","tropical","family","romance"],"commission":"hotel","wells":["stay","eat","activities"],"draw_rank":3,"tier_absent_reason":"not-established","source":"https://www.smallhope.com/packages","accessed":"2026-10-03"},{"name":"Andros Beach Club","blurb":"\"all-inclusive boutique resort on South Andros Island\" at Kemp''s Bay on four miles of beach; six room types from the Sand Dollar Studio (sleeps 2) to the Coconut Villa (sleeps 6, 1,730 sq ft); bonefishing, \"40+ dive sites and blue holes\", spearfishing, snorkelling and mangrove kayaking","si":["tropical","diveglobal","adventure","family"],"commission":"hotel","wells":["activities","eat","shop","stay"],"draw_rank":6,"tier_absent_reason":"not-established","source":"https://www.androsbeachclub.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Kamalame Cay","blurb":"\"A Private Island Escape Edged by The Andros Great Barrier Reef\": \"a 96-acre cay\" of oceanfront cottages, bungalows and villas, \"accessible via private ferry or seaplane\", with what it calls \"the only overwater spa in the Bahamas\", a freshwater pool and a three-mile beach; dining \"a la carte or all inclusive\"; (800) 790-7971, info@kamalame.com","si":["romance","tropical","wellness"],"commission":"hotel","wells":["activities","beauty","eat","move","stay"],"draw_rank":7,"tier_absent_reason":"not-established","source":"https://www.kamalame.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Bonefishing on Andros","blurb":"Ministry of Tourism: \"North Andros is separated from Central Andros by creeks and flats stocked with bonefish.\" \"Tarpon, permit, and bonefish swim these waters. They''re easy to miss, and fishing for them requires a trained eye.\" The page names local guides only by first name and lists no operator","si":["adventure","ocean","wildlife"],"wells":["activities"],"draw_rank":8,"tier_absent_reason":"not-sold","source":"https://www.bahamas.com/experiences/fly-fishing-andros","accessed":"2026-10-03","commission":"guide (fishing guide or lodge package) - operator","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - bonefishing is sold by licensed guides and fishing lodges"},{"name":"Andros Island Bonefish Club","blurb":"Cargill Creek; operating \"over 40 years\", built and managed by Captain Rupert Leadon for over 35 years; packages include lodging, guides and meals; published per person double: 3 nights/2 days $2,268 to 8 nights/7 days $6,468, with 6 nights/5 days $4,790 marked most popular; 242-357-2212, info@androsbonefishing.com","si":["adventure","ocean"],"commission":"hotel","wells":["stay","activities","eat"],"draw_rank":9,"tier_absent_reason":"not-established","source":"https://www.androsbonefishing.com/","accessed":"2026-10-03"},{"name":"Mangrove Cay Club","blurb":"\"the Bahamas'' premier saltwater fly fishing lodge. Located smack in the middle of the Andros fishery, the largest area of bonefish habitat in the world\"; \"3, 5 or 7 Night Bonefishing Getaway\" packages with \"full-time professional guides\"; +1.242.369.0731, info@mangrovecayclub.com","si":["adventure","ocean"],"commission":"hotel","wells":["stay","activities","eat"],"draw_rank":10,"tier_absent_reason":"not-established","source":"https://www.mangrovecayclub.com/","accessed":"2026-10-03"},{"name":"Swain''s Cay Lodge","blurb":"\"Bonefishing Lodge and Island Hotel\" on Mangrove Cay with an Orvis-endorsed fly-fishing programme; duplex apartment, ocean-view rooms and suites and a beach-front suite; +1 242-422-5018, fish@swainscaylodge.com","si":["adventure","tropical","ocean"],"commission":"hotel","wells":["stay","activities"],"draw_rank":11,"tier_absent_reason":"not-established","source":"https://www.swainscaylodge.com/","accessed":"2026-10-03"},{"name":"West Side National Park","blurb":"Bahamas National Trust: \"This 1.5 million-acre national park encompasses virtually the entire west side of Andros Island\"; refuge for \"the Andros Rock Iguana, Atala Hairstreak Butterfly, the West Indian Flamingo, Smalltooth Sawfish, and Sea Turtles\"; nursery flats for bonefish and tarpon; \"one of the best flats-fishing areas in the world\"; \"only accessible by boat\" with \"little infrastructure\"","si":["wildlife","adventure","expedition"],"wells":["activities","move","stay"],"draw_rank":12,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/west-side-national-park/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Blue Holes National Park","blurb":"Bahamas National Trust, North Andros, 40,000 acres, established 2002: \"22 unique inland blue holes, and the surrounding rich coppice and pineland forests\", home to the endemic Bahama Oriole and the Great Lizard Cuckoo; \"No entry fee\"; reads \"Closed temporarily\" on the date read","si":["hiking","wildlife","adventure"],"wells":["activities"],"draw_rank":13,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/blue-holes-national-park/","accessed":"2026-10-03","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"North & South Marine Parks","blurb":"Bahamas National Trust, North Andros, 5,000 acres, established 2002: \"Protects: Coral Reefs & Andros'' Barrier reef\"","si":["diveglobal","ocean","wildlife"],"wells":["activities"],"draw_rank":14,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/","accessed":"2026-10-03","commission":"operator (boat, snorkel or dive trip) - activity affiliate where listed","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - reached by boat or water - sold as a boat, snorkel or dive trip by local operators"},{"name":"Androsia Batik","blurb":"\"Androsia Hand Made Batik was established by the Birch family in 1960 on Andros Island\" (androsia.com); the Ministry of Tourism calls batik \"the unofficial national fabric of The Bahamas\" and describes factory tours where visitors \"create their very own Bahamian batik right where it all began\". Factory in Andros Town; +1 242-376-9339; online shop at androsia.com","si":["culture","family"],"commission":"venue","wells":["shop","activities"],"draw_rank":15,"tier_absent_reason":"does-not-compete","source":"https://www.androsia.com/","accessed":"2026-10-03"},{"name":"All Andros Crab Fest","blurb":"At the \"Festival Site, Fresh Creek Central Andros\": \"Bahamian cultural competitions, entertainment and all the crab you can eat\", with \"hundreds of crabs ... cooked in over 100 ways\", crabbing, dominoes, cane peeling and dance competitions; the festival \"began in 1997\". The Ministry''s news page gives \"June 13-14\" for the 18th edition and prints no year; no 2026 or 2027 date was found","si":["culinary","culture","family","entertainment"],"commission":"venue","wells":["activities","eat"],"draw_rank":16,"tier_absent_reason":"does-not-compete","source":"https://www.tourismtoday.com/news/catch-crabs-crawling","accessed":"2026-10-03"},{"name":"All Andros & Berry Islands Regatta","blurb":"Traditional Bahamian sloops race in A, B and C classes at \"Regatta Village in Morgan''s Bluff, North Andros (20 miles from San Andros Airport)\", with Bahamian food and music; listed July 9-11, 2020, contact Mr. Floyd Newton (242) 329-2278. Earlier edition July 4-7, 2019 (ewnews.com); the 2023 All Andros Regatta ran July 13-16 with the Bahamas Games (The Tribune). No 2026 date found","si":["sailing","culture","spectator"],"wells":["activities","eat","fly","stay"],"draw_rank":17,"tier_absent_reason":"not-sold","source":"https://www.tourismtoday.com/events/all-andros-berry-islands-regatta","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text","commission":"event (free to attend) - pair with Stay-Well and an event-week package","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a festival or regatta - free to attend; the stay and the package around it are the paid route"},{"name":"Crab Replenishment Reserve","blurb":"Bahamas National Trust, North Andros, 4,000 acres, established 2002: \"Protects: Important crab breeding grounds\"","si":["wildlife","expedition"],"wells":["activities"],"draw_rank":18,"tier_absent_reason":"not-sold","source":"https://bnt.bs/explore/andros/","accessed":"2026-10-03","commission":"entry non-commissionable (curated) - guide or island tour operator sells around it","commission_basis":"2026-10-05 lane label by the jewel''s nature (CC review) - a landmark, park or natural sight - free or a park fee; a guided island tour is the paid route"},{"name":"Hank''s Place Restaurant & Bar","blurb":"\"Our restaurant is unlike any other in Andros, because of its unique dining room and bar built over the water, providing guests a stunning view of Fresh Creek''s harbor.\" \"Open Monday through Saturday 2:00 p.m.-10:00 p.m.\" Queen''s Highway, Fresh Creek; (242) 368-2447, hanksplace2@outlook.com","si":["culinary","tropical"],"commission":"venue","wells":["eat","stay"],"draw_rank":19,"tier_absent_reason":"does-not-compete","source":"https://www.bahamas.com/vendor/hanks-place-restaurant-bar","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Shine''s Conch Shack","blurb":"Bahamas Out Island Promotion Board guide (April 27, 2018), northern Mangrove Cay: \"Bahamian delights such as conch salad and crack conch, in addition to chicken wings, lobster ceviche\". A guide-site source: no own page found, and the 2018 date is stated","si":["culinary","culture"],"commission":"venue","wells":["activities","eat"],"draw_rank":20,"tier_absent_reason":"does-not-compete","source":"https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"Brigadier''s Restaurant","blurb":"Bahamas Out Island Promotion Board guide (April 27, 2018), Davis Creek: \"try the lobster fritters, or a loaded hamburger at Brigadier''s Restaurant\". A guide-site source: no own page found, and the 2018 date is stated","si":["culinary"],"commission":"venue","wells":["activities","eat"],"draw_rank":21,"tier_absent_reason":"does-not-compete","source":"https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Sammy''s Bar and Grill","blurb":"Bahamas Out Island Promotion Board guide (April 27, 2018), Queen''s Highway, North Andros: \"you may want to taste the lobster bites, conch burger or conch salad\". A guide-site source: no own page found, and the 2018 date is stated","si":["culinary"],"commission":"venue","wells":["activities","eat"],"draw_rank":22,"tier_absent_reason":"does-not-compete","source":"https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text + food SI (David 2026-10-05: every traveler has to eat)"},{"name":"Ezrena''s Restaurant","blurb":"Bahamas Out Island Promotion Board guide (April 27, 2018), Drigg''s Hill, South Andros: \"Be sure to try their boil fish and johnny cake! Eat authentic Bahamian food at Ezrena''s.\" A guide-site source: no own page found, and the 2018 date is stated","si":["culinary","culture"],"commission":"venue","wells":["activities","eat"],"draw_rank":23,"tier_absent_reason":"does-not-compete","source":"https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Western Air","blurb":"San Andros is \"Home of Western Air\" and \"just a 12 minute flight from Nassau & was the first airport Western Air began flights!\"; also serves Congo Town, which it calls \"the bone fishing capital of the world\"; booked at westernair.flythebahamas.com","si":["tropical"],"commission":"operator","wells":["activities","fly","move"],"draw_rank":24,"tier_absent_reason":"does-not-compete","source":"https://www.westernairbahamas.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"},{"name":"Makers Air","blurb":"\"Scheduled and On-Demand Flights Across Florida and the Bahamas\" from Fort Lauderdale (2331 Northwest 55th Court) to San Andros, Fresh Creek and Congo Town; booked through a FareHarbor widget at book.makerssuite.com","si":["tropical","privatejet"],"commission":"operator","wells":["activities","fly","move","stay"],"draw_rank":25,"tier_absent_reason":"does-not-compete","source":"https://makersair.com/","accessed":"2026-10-03","wells_basis":"full pass 2026-10-05, additive — text"}],"faq":[{"q":"What is worth doing in Andros?","a":"Tongue of the Ocean wall dive — vertical wall at the 6,000-ft blue abyss edge.","source":"https://www.takeyourbackpack.com/backpacking-in-bahamas/visit-andros-barrier-reef/"},{"q":"How do I get to Andros Island from Nassau?","a":"By air. Small Hope Bay Lodge lists Titan Air, which \"Departs Nassau at 7 am & 4 pm and offers return flights (no flights on Saturday)\", and Le Air, which \"Departs Nassau at 6:45 am & 3 pm and offers return flights (no flights on Sunday)\", plus charter aircraft. Western Air says San Andros \"is just a 12 minute flight from Nassau\" and also serves Congo Town. The Titan Air and Le Air times are a lodge''s list, not the carriers'' timetables.","source":"https://www.smallhope.com/how-to-get-here","accessed":"2026-10-03"},{"q":"What are the airports on Andros Island?","a":"The Ministry of Tourism names three: San Andros Airport (SAQ) in North Andros near Nicholls Town, Andros Town International Airport (ASD) in Central Andros at Fresh Creek, and South Andros Airport (TZN) near Congo Town.","source":"https://www.bahamas.com/islands/andros","accessed":"2026-10-03"},{"q":"What is the best time to visit Andros Island, Bahamas?","a":"No page read names a best time, so none is given. What is published: NOAA says \"The Atlantic hurricane season runs from June 1 to November 30\" with a peak on September 10 and \"most activity occurring between mid-August and mid-October\". Small Hope Bay Lodge prices High Season as Feb 16-May 17 and Dec 16-Jan 5, and Low Season as Jan 6-Feb 15 and May 18-Dec 15 (https://www.smallhope.com/packages).","source":"https://www.nhc.noaa.gov/climo/","accessed":"2026-10-03"},{"q":"What are the blue holes of Andros, Bahamas?","a":"The Ministry of Tourism says \"Andros has more than 180 blue holes found inland and along its shore\" (https://www.bahamas.com/islands/andros). Blue Holes National Park in North Andros protects \"22 unique inland blue holes\", among them Captain Bill''s Blue Hole, \"nearly perfectly round\" with \"a depth of 100+ feet\". The park charges \"No entry fee\" but reads \"Closed temporarily\" on the Bahamas National Trust page read on 2026-10-03.","source":"https://bnt.bs/explore/andros/blue-holes-national-park/","accessed":"2026-10-03"},{"q":"Where should I stay in Andros, Bahamas?","a":"The Ministry of Tourism divides the island into North, Central and South Andros and Mangrove Cay. Lodges read for this build: in Central Andros, Small Hope Bay Lodge (all-inclusive, since 1960), Kamalame Cay (a private island) and Andros Island Bonefish Club at Cargill Creek; on Mangrove Cay, Mangrove Cay Club and Swain''s Cay Lodge; in South Andros, Andros Beach Club at Kemp''s Bay. Each is sourced on its own jewel in this dossier.","source":"https://www.bahamas.com/islands/andros","accessed":"2026-10-03"},{"q":"Are there all-inclusive resorts on Andros, Bahamas?","a":"Yes, on the pages read. Small Hope Bay Lodge''s all-inclusive covers \"All Meals and Open Bar\", bikes and kayaks, diving and snorkelling lessons, nature tours and babysitting, at a published adult rate of $375 per day in low season and $425 in high season. Andros Beach Club calls itself an \"all-inclusive boutique resort on South Andros Island\" (https://www.androsbeachclub.com/), and Kamalame Cay offers dining \"a la carte or all inclusive\" (https://www.kamalame.com/).","source":"https://www.smallhope.com/packages","accessed":"2026-10-03"},{"q":"When is the Andros Crab Fest?","a":"In June, at the \"Festival Site, Fresh Creek Central Andros\". The Ministry of Tourism''s news page gives \"June 13-14\" for the 18th edition of a festival that \"began in 1997\", and does not print the year. No 2026 or 2027 date was found on any page read.","source":"https://www.tourismtoday.com/news/catch-crabs-crawling","accessed":"2026-10-03"},{"q":"When is the Andros regatta?","a":"In July, at Morgan''s Bluff, North Andros, on the editions read. The Ministry of Tourism listed the All Andros & Berry Islands Regatta for July 9-11, 2020, at \"Regatta Village in Morgan''s Bluff\", with A, B and C class sloops; the 2019 edition ran July 4-7 (ewnews.com) and the 2023 All Andros Regatta July 13-16 alongside the Bahamas Games (The Tribune). No 2026 date was found.","source":"https://www.tourismtoday.com/events/all-andros-berry-islands-regatta","accessed":"2026-10-03"},{"q":"What is Andros known for?","a":"The Ministry of Tourism: \"The largest island in The Bahamas, Andros remains virtually untouched.\" It names more than 180 blue holes, the Andros Barrier Reef, bonefish flats, and Androsia batik at Fresh Creek, \"handmade batik since 1970s\" on its island page. Androsia''s own site says it was \"established by the Birch family in 1960\".","source":"https://www.bahamas.com/islands/andros","accessed":"2026-10-03"},{"q":"What are the restaurants on Andros, Bahamas?","a":"Hank''s Place on Queen''s Highway, Fresh Creek, has a \"dining room and bar built over the water\" and is \"Open Monday through Saturday 2:00 p.m.-10:00 p.m.\"; (242) 368-2447. A 2018 Out Islands guide also names Brigadier''s (Davis Creek), Shine''s Conch Shack (Mangrove Cay), Sammy''s Bar and Grill (North Andros) and Ezrena''s (Drigg''s Hill, South Andros) - https://myoutislands.com/blog/boi-news/awaken-your-taste-buds-in-andros.","source":"https://www.bahamas.com/vendor/hanks-place-restaurant-bar","accessed":"2026-10-03"},{"q":"How big is Andros?","a":"The Ministry of Tourism calls it \"The largest island in The Bahamas\" (https://www.bahamas.com/islands/andros). The Bahamas National Trust''s West Side National Park alone is \"1.5 million-acre\" and \"encompasses virtually the entire west side of Andros Island\". No total land area was read on a government page.","source":"https://bnt.bs/explore/andros/west-side-national-park/","accessed":"2026-10-03"}],"seo":{"meta_title":"Andros Bahamas: Barrier Reef, Wall & Blue Holes","meta_description":"Dive the world''s third-longest barrier reef, the Tongue of the Ocean wall and Andros blue holes from legacy dive lodges. When to go and how.","slug":"andros-bahamas","primary_keyword":"Andros barrier reef diving","long_tail":["Tongue of the Ocean wall dive","Andros blue holes diving","Small Hope Bay Lodge Andros","Andros bonefishing","Andros Bahamas diving"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-02","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-02","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/bahamas","read":"2026-08-20T14:54:09Z","source_updated":"2026-05-28T17:01:45+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"diveglobal","status":"live"}],"ultra":null,"source_verified":"2026-07-02","hero":{"query":"Andros, Bahamas"},"geo":{"lat":24.4333,"lng":-77.95},"orbit":[{"id":"abaco-bahamas","jewels":3,"si":["tropical","yacht"]},{"id":"bimini-bahamas","jewels":3,"si":["diveglobal"]},{"id":"eleuthera-bahamas","jewels":3,"si":["tropical","diveglobal","expedition"]},{"id":"exuma-bahamas","jewels":3,"si":["expedition","liveaboard"]},{"id":"grand-bahama-freeport-bahamas","jewels":3,"si":["diveglobal","liveaboard","expedition"]},{"id":"harbour-island-bahamas","jewels":3,"si":["tropical","ultra","culture"]},{"id":"long-island-bahamas","jewels":3,"si":["tropical","expedition","diveglobal"]},{"id":"nassau-paradise-island-bahamas","jewels":3,"si":["romance","diveglobal","liveaboard"]}],"orbit_country":[]}'::jsonb, 12),
